/* Contenido de «Francés básico A1». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("c-frances-a1",{"l":{"c-frances-a1-m1-l1":[{"tipo":"destacado","texto":"<b>Antes de empezar:</b> este es un <b>curso libre de capacitación</b> con constancia de Instituto Mara. Trabaja las habilidades del nivel <b>A1 del Marco Común Europeo (MCER)</b>: el de quien empieza y ya puede presentarse, dar sus datos y resolver situaciones sencillas de la vida diaria. <b>No es una certificación oficial de francés</b> como el <b>DELF A1</b>, ni tiene validez oficial ante la SEP. Si una escuela, una empresa o un trámite (por ejemplo, para estudiar en Francia o emigrar a Quebec) te pide un nivel certificado, tendrás que presentar ese examen por tu cuenta en un centro autorizado, como las Alianzas Francesas."},{"tipo":"texto","texto":"En Francia, <b>Bonjour</b> es casi una palabra mágica: se dice al entrar a una tienda, al subir al camión, al hablar con la recepcionista, incluso antes de preguntar una dirección. Pedir algo sin decir <i>Bonjour</i> primero se considera grosero. La buena noticia: con cinco o seis fórmulas ya quedas bien en cualquier lugar.<br><br><b>Cómo leer la pronunciación aproximada</b> que verás en todo el curso: <b>ü</b> = la u francesa (di «i» con la boca en forma de «u»); <b>ö</b> = el sonido de <i>eu</i>, parecido a una «e» con labios redondos; <b>ã, õ, ẽ</b> = vocales nasales (el aire sale también por la nariz y la n no se pronuncia); <b>y</b> = la j francesa, como la «y» de un argentino en «yo»; <b>sh</b> = como cuando pides silencio; <b>z</b> = una s que zumba, como abeja. La r francesa se hace en la garganta, casi como una j suave."},{"tipo":"tabla","titulo":"Saludos y despedidas","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español","Cuándo"],"filas":[["Bonjour!","bõyúr","Buenos días / Buenas tardes","Todo el día, hasta que oscurece"],["Bonsoir!","bõsuár","Buenas noches (al llegar)","En la noche, al saludar"],["Salut!","salü","¡Hola! / ¡Bye!","Solo con amigos; sirve para llegar y para irse"],["Au revoir!","o rvuár","Adiós","Siempre funciona"],["Bonne journée!","bon yurné","Que tengas buen día","Al despedirte de día"],["Bonne soirée!","bon suaré","Que tengas buena noche","Al despedirte en la tarde o noche"],["À bientôt!","a biẽtó","Hasta pronto","Si se van a volver a ver"],["Merci!","mersí","Gracias","Siempre; con <i>beaucoup</i> es «muchas gracias»"],["S'il vous plaît.","sil vu plé","Por favor","Al pedir algo"]],"nota":"Agrega <b>madame</b> (señora) o <b>monsieur</b> (señor) después del saludo: <i>Bonjour, madame.</i> Suena mucho más amable."},{"tipo":"comparar","titulo":"«Buenas noches» no siempre es bonne nuit","malTitulo":"Evita","mal":"Llegar a un restaurante a las 9 p. m. y decir <i>Bonne nuit!</i><br>Decir solo <i>Un café</i> al llegar a la barra.","bienTitulo":"Correcto","bien":"<i><b>Bonsoir</b>, monsieur!</i> para saludar en la noche. <i>Bonne nuit</i> es solo para irse a dormir.<br><i>Bonjour, un café, s'il vous plaît.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Recepción de un hotel en Cancún","lineas":[{"quien":"Karla","en":"Bonjour, madame. Bienvenue à Cancún!","es":"Buenas tardes, señora. ¡Bienvenida a Cancún!"},{"quien":"Mme Martin","en":"Bonjour! Merci beaucoup.","es":"¡Buenas tardes! Muchas gracias."},{"quien":"Karla","en":"Comment allez-vous?","es":"¿Cómo está?"},{"quien":"Mme Martin","en":"Très bien, merci. Et vous?","es":"Muy bien, gracias. ¿Y usted?"},{"quien":"Karla","en":"Très bien, merci. Voici votre clé: chambre 204.","es":"Muy bien, gracias. Aquí está su llave: habitación 204."},{"quien":"Mme Martin","en":"Merci. Bonne journée!","es":"Gracias. ¡Que tenga buen día!"},{"quien":"Karla","en":"Merci, vous aussi. Au revoir, madame.","es":"Gracias, igualmente. Hasta luego, señora."}]},{"tipo":"practica","rotulo":"¿Qué dices?","preguntas":[{"p":"Son las 9 de la noche y llegas a la recepción del hotel. Dices…","ops":["Bonne nuit!","Bonsoir!","Bonne journée!"],"correcta":1,"explica":"Para <b>saludar</b> en la noche: <b>Bonsoir</b>. <i>Bonne nuit</i> es para irse a dormir."},{"p":"Entras a una panadería a las 10 de la mañana. Lo primero que dices es…","ops":["Un croissant.","Salut!","Bonjour, madame."],"correcta":2,"explica":"Siempre <b>Bonjour</b> primero; <i>Salut</i> es solo para amigos."},{"p":"Te despides de un amigo en la calle. ¿Qué es natural?","ops":["Salut! À bientôt!","Bonsoir, monsieur.","Bienvenue!"],"correcta":0},{"p":"<i>Bonne journée!</i> significa…","ops":["Buen viaje","Que tengas buen día","Buenos días (al llegar)"],"correcta":1,"explica":"Se usa al <b>despedirse</b>; para llegar se dice <i>Bonjour</i>."},{"p":"Alguien te dice <i>Merci!</i> Tú contestas…","ops":["De rien.","Bonsoir.","Au revoir, merci."],"correcta":0,"explica":"<b>De rien</b> = de nada. Más formal: <i>Je vous en prie.</i>"}]},{"tipo":"relacionar","rotulo":"Relaciona cada fórmula con su significado","voz":true,"pares":[["Au revoir","Adiós"],["À demain","Hasta mañana"],["À bientôt","Hasta pronto"],["De rien","De nada"],["Bienvenue","Bienvenido"],["Merci beaucoup","Muchas gracias"]]},{"tipo":"pronunciar","rotulo":"Dilo en voz alta","frases":[{"en":"Bonjour, madame.","pron":"bõyúr madám","es":"Buenos días, señora."},{"en":"Bonsoir, monsieur.","pron":"bõsuár mösiö","es":"Buenas noches, señor."},{"en":"Merci beaucoup!","pron":"mersí bocú","es":"¡Muchas gracias!"},{"en":"Un café, s'il vous plaît.","pron":"ẽ kafé sil vu plé","es":"Un café, por favor."},{"en":"Au revoir, à demain!","pron":"o rvuár a dömẽ","es":"¡Adiós, hasta mañana!"}]},{"tipo":"clave","items":["<b>Bonjour</b> de día y <b>Bonsoir</b> de noche; <i>Bonne nuit</i> solo para dormir.","Di <i>Bonjour</i> antes de pedir cualquier cosa, y agrega <i>madame</i> o <i>monsieur</i>.","<b>Salut</b> es informal; <b>Au revoir</b> funciona siempre.","Este curso es libre, con constancia de Instituto Mara; no sustituye el DELF A1."]}],"c-frances-a1-m1-l2":[{"tipo":"texto","texto":"Como en español, el francés tiene dos formas de dirigirse a alguien: <b>tu</b> (tú) y <b>vous</b> (usted). Pero ojo con dos diferencias: <b>1)</b> en Francia se usa <i>vous</i> mucho más que «usted» en México: con desconocidos (aunque sean jóvenes), clientes, jefes, meseros y personas mayores. <b>2)</b> <i>vous</i> también es el plural: «ustedes» siempre es <i>vous</i>, aunque sean tus amigos. Si no sabes cuál usar, usa <i>vous</i> y espera a que la otra persona te proponga: <i>On peut se tutoyer?</i> (¿Nos hablamos de tú?). En Quebec se tutea más rápido."},{"tipo":"tabla","titulo":"Las mismas preguntas, dos registros","voz":true,"colVoz":0,"encabezados":["Francés","Registro","Español"],"filas":[["Salut! Ça va?","tu","¡Hola! ¿Qué tal?"],["Ça va bien, et toi?","tu","Bien, ¿y tú?"],["Comment vas-tu?","tu","¿Cómo estás?"],["Comment allez-vous?","vous","¿Cómo está usted? / ¿Cómo están?"],["Très bien, merci. Et vous?","vous","Muy bien, gracias. ¿Y usted?"],["Excuse-moi.","tu","Perdón / Disculpa."],["Excusez-moi.","vous","Disculpe."],["Pas mal.","los dos","No tan mal / Más o menos bien."]],"nota":"<i>Ça va?</i> es comodín: sirve para preguntar y para contestar. <i>Ça va? — Ça va!</i>"},{"tipo":"comparar","titulo":"«¿Cómo estás?» no se traduce palabra por palabra","malTitulo":"Evita","mal":"<i>Comment tu es?</i> (eso significa «¿cómo eres?»)<br><i>Je suis bien.</i> (suena a «estoy cómodo»)","bienTitulo":"Correcto","bien":"<i><b>Comment vas-tu?</b> / <b>Ça va?</b></i><br><i><b>Je vais bien</b>, merci.</i> (literal: «voy bien»)"},{"tipo":"dialogo","titulo":"Diálogo — Oficina de una empresa francesa en Querétaro","lineas":[{"quien":"Julien","en":"Salut, Diego! Ça va?","es":"¡Hola, Diego! ¿Qué tal?"},{"quien":"Diego","en":"Salut, Julien! Ça va bien, et toi?","es":"¡Hola, Julien! Bien, ¿y tú?"},{"quien":"Julien","en":"Très bien. Diego, je te présente madame Leroy, la directrice.","es":"Muy bien. Diego, te presento a la señora Leroy, la directora."},{"quien":"Diego","en":"Bonjour, madame. Enchanté. Comment allez-vous?","es":"Buenos días, señora. Mucho gusto. ¿Cómo está?"},{"quien":"Mme Leroy","en":"Très bien, merci. Et vous?","es":"Muy bien, gracias. ¿Y usted?"},{"quien":"Diego","en":"Je vais bien, merci.","es":"Estoy bien, gracias."}]},{"tipo":"practica","rotulo":"¿Tu o vous?","preguntas":[{"p":"Hablas con un niño de 8 años.","ops":["vous","il","nous","tu"],"correcta":3,"explica":"Con niños, familia y amigos usas <b>tu</b>; <i>il</i> es «él» y <i>nous</i> es «nosotros», no sirven para hablarle a alguien."},{"p":"Atiendes a un huésped en el hotel.","ops":["vous","il","tu","nous"],"correcta":0,"explica":"Con clientes, siempre <b>vous</b>. En francés no se le habla a alguien en tercera persona como con «usted»: <i>il</i> es «él»."},{"p":"Hablas con dos amigas a la vez.","ops":["tu","vous","nous","elles"],"correcta":1,"explica":"«Ustedes» siempre es <b>vous</b>, aunque sean amigas; <i>elles</i> es «ellas», para hablar de ellas, no con ellas."},{"p":"Le preguntas la hora a un desconocido de tu edad en la calle.","ops":["tu","il","vous","on"],"correcta":2,"explica":"Con desconocidos, <b>vous</b>, aunque sean jóvenes; <i>il</i> es «él» y <i>on</i> equivale a «nosotros» o «se»."},{"p":"«Estoy bien, gracias» se dice…","ops":["Je suis bien, merci.","Je vais bien, merci.","Je va bien, merci."],"correcta":1}]},{"tipo":"completar","rotulo":"Completa el saludo","voz":true,"items":[{"frase":"Salut, ça ___?","resp":["va"],"es":"¡Hola! ¿Qué tal?"},{"frase":"Bonjour, madame. Comment ___-vous?","resp":["allez"],"es":"Buenos días, señora. ¿Cómo está?"},{"frase":"Je ___ bien, merci.","resp":["vais"],"es":"Estoy bien, gracias."},{"frase":"Ça va bien, et ___?","resp":["toi"],"es":"Bien, ¿y tú?"},{"frase":"Excusez-___, monsieur.","resp":["moi"],"es":"Disculpe, señor."}]},{"tipo":"escuchar","rotulo":"Escucha y repite","frases":[{"en":"Comment allez-vous?","pron":"komã talé vu","es":"¿Cómo está usted?"},{"en":"Ça va bien, et toi?","pron":"sa va biẽ, e tuá","es":"Bien, ¿y tú?"},{"en":"Je vais très bien, merci.","pron":"yö vé tre biẽ mersí","es":"Estoy muy bien, gracias."},{"en":"On peut se tutoyer?","pron":"õ pö sö tütuayé","es":"¿Nos hablamos de tú?"}]},{"tipo":"clave","items":["<b>tu</b> con amigos, familia y niños; <b>vous</b> con clientes, jefes y desconocidos.","«Ustedes» siempre es <b>vous</b>.","«¿Cómo estás?» = <i>Ça va? / Comment vas-tu? / Comment allez-vous?</i>","«Estoy bien» = <i><b>Je vais</b> bien</i>, no <i>je suis bien</i>."]}],"c-frances-a1-m1-l3":[{"tipo":"texto","texto":"Con cuatro frases ya te puedes presentar: <b>Je m'appelle…</b> (me llamo), <b>Je suis…</b> (soy), <b>J'habite à…</b> (vivo en) y <b>Je travaille…</b> (trabajo). Fíjate en un detalle muy francés: <i>je</i> se convierte en <b>j'</b> antes de vocal o de h: <i>j'habite, j'aime</i>. Y las nacionalidades cambian si eres mujer: <i>mexicain</i> → <i>mexicain<b>e</b></i>. Lo mismo con <i>enchanté</i> (mucho gusto): una mujer escribe <i>enchantée</i>, aunque suena igual."},{"tipo":"tabla","titulo":"Frases para presentarte","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["Je m'appelle Laura.","Me llamo Laura."],["Moi, c'est Diego.","Yo soy Diego. (más relajado)"],["Je suis mexicain.","Soy mexicano."],["Je suis mexicaine.","Soy mexicana."],["Je suis de Puebla.","Soy de Puebla."],["J'habite à Mérida.","Vivo en Mérida."],["J'habite au Mexique.","Vivo en México (el país)."],["Je travaille dans un hôtel.","Trabajo en un hotel."],["Comment vous appelez-vous?","¿Cómo se llama usted?"],["Vous êtes d'où?","¿De dónde es usted?"]],"nota":"<b>Mexique</b> es el país; <b>Mexico</b> es la Ciudad de México. Ciudades con <b>à</b> (<i>à Monterrey</i>); el país con <b>au</b> (<i>au Mexique</i>), y Francia con <b>en</b> (<i>en France</i>)."},{"tipo":"comparar","titulo":"Calcos que delatan al hispanohablante","malTitulo":"Evita","mal":"<i>Mon nom est Laura.</i> (se entiende, pero suena rígido)<br><i>J'habite en Mérida.</i><br><i>Je suis de le Mexique.</i>","bienTitulo":"Correcto","bien":"<i><b>Je m'appelle</b> Laura.</i><br><i>J'habite <b>à</b> Mérida.</i><br><i>Je suis <b>du</b> Mexique.</i> (de + le = du)"},{"tipo":"dialogo","titulo":"Diálogo — Recorrido turístico en Oaxaca","lineas":[{"quien":"Rodrigo","en":"Bonjour à tous! Je m'appelle Rodrigo. Je suis votre guide aujourd'hui.","es":"¡Buenos días a todos! Me llamo Rodrigo. Soy su guía hoy."},{"quien":"Claire","en":"Bonjour, Rodrigo! Moi, c'est Claire. Et voici mon mari, Marc.","es":"¡Buenos días, Rodrigo! Yo soy Claire. Y este es mi esposo, Marc."},{"quien":"Marc","en":"Enchanté!","es":"¡Mucho gusto!"},{"quien":"Rodrigo","en":"Enchanté! Vous êtes d'où?","es":"¡Mucho gusto! ¿De dónde son?"},{"quien":"Claire","en":"Nous sommes canadiens, de Montréal. Et vous, vous êtes d'ici?","es":"Somos canadienses, de Montreal. ¿Y usted, es de aquí?"},{"quien":"Rodrigo","en":"Oui, je suis d'Oaxaca, mais j'habite à Mexico.","es":"Sí, soy de Oaxaca, pero vivo en la Ciudad de México."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"Una mujer dice «Mucho gusto». Escribe…","ops":["Enchanté","Enchantée","Enchantés"],"correcta":1,"explica":"En femenino se agrega <b>-e</b>; suena igual."},{"p":"«Vivo en Guadalajara»","ops":["J'habite à Guadalajara.","J'habite en Guadalajara.","Je habite à Guadalajara."],"correcta":0,"explica":"Ciudades con <b>à</b>, y <i>je</i> se vuelve <b>j'</b> antes de h."},{"p":"Una francesa te dice <i>J'habite à Mexico</i>. ¿Dónde vive?","ops":["En algún lugar del país","En la Ciudad de México","En Nuevo México"],"correcta":1},{"p":"Rodrigo es hombre. Dice: <i>Je suis…</i>","ops":["mexicaine","mexicaines","mexicains","mexicain"],"correcta":3,"explica":"Rodrigo es uno y es hombre: masculino singular, <b>mexicain</b>, sin <i>e</i> ni <i>s</i> al final."},{"p":"«¿Cómo se llama usted?»","ops":["Comment vous appelez-vous?","Comment est votre nom?","Qui vous appelez?"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Arma la presentación","voz":true,"items":[{"frase":"Je m'appelle Ana et je suis mexicaine","es":"Me llamo Ana y soy mexicana"},{"frase":"J'habite à Monterrey","es":"Vivo en Monterrey"},{"frase":"Je travaille dans un hôtel à Cancún","es":"Trabajo en un hotel en Cancún"},{"frase":"Vous êtes d'où?","es":"¿De dónde es usted?"}]},{"tipo":"pronunciar","rotulo":"Preséntate en voz alta","frases":[{"en":"Je m'appelle Diego.","pron":"yö mapél diégo","es":"Me llamo Diego."},{"en":"Je suis mexicain.","pron":"yö süí meksikẽ","es":"Soy mexicano."},{"en":"Je suis mexicaine.","pron":"yö süí meksikén","es":"Soy mexicana."},{"en":"J'habite au Mexique.","pron":"yabít o meksík","es":"Vivo en México."},{"en":"Enchanté!","pron":"ãshãté","es":"¡Mucho gusto!"}]},{"tipo":"reflexion","rotulo":"Tu presentación","pregunta":"Escribe tu presentación en cuatro frases: tu nombre, tu nacionalidad, la ciudad donde vives y dónde trabajas o estudias. Luego dila en voz alta tres veces, sin leer.","ayuda":"Bonjour! Je m'appelle… Je suis mexicain / mexicaine. J'habite à… Je travaille dans… / Je suis étudiant(e)."},{"tipo":"clave","items":["<i>Je m'appelle…, je suis…, j'habite à…, je travaille…</i>","<i>je</i> → <b>j'</b> antes de vocal o h.","Femenino con <b>-e</b>: <i>mexicaine, enchantée</i>.","<b>Mexique</b> = el país · <b>Mexico</b> = la capital."]}],"c-frances-a1-m1-l4":[{"tipo":"texto","texto":"<b>Être</b> es el verbo más importante del francés y cubre casi todo lo que en español dividimos entre <b>ser</b> y <b>estar</b>: <i>Je suis mexicain</i> (soy), <i>Je suis fatigué</i> (estoy cansado). Una diferencia enorme con el español: en francés <b>el pronombre es obligatorio</b>. En español decimos «soy de León»; en francés nunca se quita el <i>je</i>, porque muchas formas del verbo suenan igual."},{"tipo":"tabla","titulo":"Être en presente","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español"],"filas":[["je suis","yö süí","yo soy / estoy"],["tu es","tü é","tú eres / estás"],["il est","il é","él es / está"],["elle est","el é","ella es / está"],["on est","õ né","nosotros somos (informal)"],["nous sommes","nu som","nosotros somos / estamos"],["vous êtes","vu zét","usted es · ustedes son"],["ils sont","il sõ","ellos son / están"],["elles sont","el sõ","ellas son / están"]],"nota":"<i>tu es</i> e <i>il est</i> suenan igual («é»). <b>on</b> se usa muchísimo en la conversación en lugar de <i>nous</i>: <i>On est prêts!</i> (¡Estamos listos!)."},{"tipo":"comparar","titulo":"No quites el pronombre y usa c'est","malTitulo":"Evita","mal":"<i>Suis fatigué.</i><br><i>Il est un collègue.</i><br><i>Elle est professeure?</i> sin cambiar la entonación","bienTitulo":"Correcto","bien":"<i><b>Je</b> suis fatigué.</i><br><i><b>C'est</b> un collègue.</i> (con un/une, usa <i>c'est</i>)<br><i>Elle est professeure?</i> con la voz subiendo al final"},{"tipo":"escuchar","rotulo":"Escucha frases con être","frases":[{"en":"C'est mon collègue, Julien.","pron":"sé mõ kolég yüliẽ","es":"Es mi compañero de trabajo, Julien."},{"en":"Elle est très sympa.","pron":"el é tre sẽpá","es":"Ella es muy buena onda."},{"en":"Nous sommes de Guadalajara.","es":"Somos de Guadalajara."},{"en":"Vous êtes française?","pron":"vu zét frãséz","es":"¿Usted es francesa?"},{"en":"Ils sont en retard.","pron":"il sõ tã rtár","es":"Van tarde. / Llegan tarde."},{"en":"Je suis fatigué.","es":"Estoy cansado."}]},{"tipo":"practica","rotulo":"Elige la forma de être","preguntas":[{"p":"Nous ___ mexicains.","ops":["sont","sommes","êtes"],"correcta":1},{"p":"Vous ___ le nouveau technicien?","ops":["êtes","est","es"],"correcta":0},{"p":"Marie et Sophie ___ de Lyon.","ops":["est","sont","sommes"],"correcta":1,"explica":"Dos personas = <b>elles sont</b>."},{"p":"Te presentan a alguien y dices «Es mi jefa».","ops":["Elle est ma cheffe.","C'est ma cheffe.","Est ma cheffe."],"correcta":1,"explica":"Con <i>ma, un, une…</i> se usa <b>c'est</b>."},{"p":"«Estoy cansada» (lo dice una mujer)","ops":["Suis fatiguée.","Je suis fatiguée.","Je es fatiguée."],"correcta":1}]},{"tipo":"completar","rotulo":"Completa con être","voz":true,"items":[{"frase":"Nous ___ de Monterrey.","resp":["sommes"],"es":"Somos de Monterrey."},{"frase":"Vous ___ professeur?","resp":["êtes"],"es":"¿Usted es maestro?"},{"frase":"Elle ___ de Lyon.","resp":["est"],"es":"Ella es de Lyon."},{"frase":"Ils ___ au bureau.","resp":["sont"],"es":"Están en la oficina."},{"frase":"Tu ___ fatigué?","resp":["es"],"es":"¿Estás cansado?"},{"frase":"___ un bon restaurant.","resp":["C'est","Cest"],"es":"Es un buen restaurante."}]},{"tipo":"tarjetas","rotulo":"Memoriza être","voz":true,"vozEn":"reverso","instruccion":"Ves la forma en español; di la forma en francés antes de voltear.","tarjetas":[{"frente":"yo soy / estoy","reverso":"je suis","ej":"Je suis de Puebla."},{"frente":"tú eres / estás","reverso":"tu es","ej":"Tu es prêt?"},{"frente":"ella es / está","reverso":"elle est","ej":"Elle est ingénieure."},{"frente":"nosotros somos","reverso":"nous sommes","ej":"Nous sommes collègues."},{"frente":"usted es · ustedes son","reverso":"vous êtes","ej":"Vous êtes d'où?"},{"frente":"ellos son / están","reverso":"ils sont","ej":"Ils sont en vacances."}]},{"tipo":"clave","items":["<b>être</b> = ser y estar: <i>je suis, tu es, il est, nous sommes, vous êtes, ils sont</i>.","El pronombre (<i>je, tu, il…</i>) nunca se quita.","Para presentar con <i>un, une, mon, ma</i>: <b>c'est</b>.","<b>on</b> = «nosotros» en la conversación diaria."]}],"c-frances-a1-m1-l5":[{"tipo":"texto","texto":"El francés se escribe con muchas letras que no suenan, pero sus reglas son bastante regulares. Esta lección te da las cinco claves que más le sirven a un hispanohablante: <b>1)</b> la r de garganta, <b>2)</b> la diferencia entre <i>u</i> y <i>ou</i>, <b>3)</b> las vocales nasales, <b>4)</b> las letras finales mudas y <b>5)</b> la <i>liaison</i>. Además, en francés el acento de la palabra cae casi siempre en la <b>última sílaba</b>: <i>restaurant, Mexique, café</i>."},{"tipo":"tabla","titulo":"Las letras que más confunden al deletrear","voz":true,"colVoz":1,"encabezados":["Letra","Ejemplo","Se dice aprox."],"filas":[["E","euro","ö"],["I","ici","i"],["G","garage","yé"],["J","Japon","yi"],["H","hôtel","ash"],["R","rue","er"],["U","une","ü"],["W","week-end","dublö vé"],["Y","yoga","i grec"]],"nota":"Para pedir que alguien deletree: <i>Ça s'écrit comment?</i> (¿Cómo se escribe?). Ojo: la <b>G</b> suena «yé» y la <b>J</b> suena «yi»; son las que más se confunden al dar un correo por teléfono."},{"tipo":"tabla","titulo":"Los sonidos clave","voz":true,"colVoz":1,"encabezados":["Sonido","Ejemplos","Cómo hacerlo"],"filas":[["r","Paris, merci, rouge","En la garganta, como una j suave que vibra un poco. Nunca la r de «perro»."],["u","tu, salut, rue","Di «i» y, sin mover la lengua, pon los labios como para silbar."],["ou","vous, bonjour, rouge","Es nuestra «u» de siempre."],["an / en","France, enfant, trente","«a» nasal (ã): la boca abierta, el aire por la nariz."],["on","bonjour, non, maison","«o» nasal (õ), con labios redondos."],["in / ain","vin, pain, mexicain","«e» nasal (ẽ), casi como decir «en» sin cerrar la n."],["eu","deux, bleu, monsieur","Di «e» con los labios redondos (ö)."]]},{"tipo":"comparar","titulo":"Las letras finales casi nunca suenan","malTitulo":"Evita","mal":"«Pa-rís» con s · «pe-tít» con t · «ils parl-ent» con -ent · «beaucoup» con p","bienTitulo":"Correcto","bien":"<i>Paris</i> = pari · <i>petit</i> = pöti · <i>ils parlent</i> = il parl · <i>beaucoup</i> = bocú<br>Regla práctica: las consonantes finales se callan, <b>salvo</b> muchas veces c, r, f, l (piensa en la palabra inglesa <i>CaReFuL</i>): <i>avec, bonjour, neuf, hôtel</i>."},{"tipo":"escuchar","rotulo":"La liaison: letras mudas que despiertan","frases":[{"en":"les amis","pron":"le zamí","es":"los amigos (la s suena como z)"},{"en":"vous êtes","pron":"vu zét","es":"usted es"},{"en":"ils ont","pron":"il zõ","es":"ellos tienen"},{"en":"ils sont","pron":"il sõ","es":"ellos son (¡sin liaison!)"},{"en":"C'est un ami.","pron":"sé tẽ namí","es":"Es un amigo."},{"en":"deux enfants","pron":"dö zãfã","es":"dos niños"}]},{"tipo":"practica","rotulo":"¿Cómo suena?","preguntas":[{"p":"¿Qué palabra tiene la «u» francesa (ü)?","ops":["vous","rue","bonjour"],"correcta":1,"explica":"<i>ou</i> es nuestra u; la <b>u</b> sola es la ü."},{"p":"<i>rue</i> (calle) y <i>roue</i> (rueda) se distinguen por…","ops":["la r","la ü contra la u","la e final"],"correcta":1},{"p":"¿Cómo se pronuncia <i>Paris</i> en francés?","ops":["París, con s","Parí, sin s","Pa-ri-se"],"correcta":1},{"p":"En <i>les amis</i>, la s final…","ops":["no se pronuncia","suena como z y se une a <i>amis</i>","suena como s fuerte"],"correcta":1,"explica":"Eso es la <b>liaison</b>: la consonante muda se pronuncia cuando la siguiente palabra empieza con vocal."},{"p":"Al deletrear tu correo, «G» se dice…","ops":["yé","yi","gue"],"correcta":0}]},{"tipo":"pronunciar","rotulo":"Entrena la boca","frases":[{"en":"La rue est très jolie.","pron":"la rü é tre yolí","es":"La calle es muy bonita."},{"en":"Un croissant, s'il vous plaît.","pron":"ẽ kruasã sil vu plé","es":"Un cuernito, por favor."},{"en":"Du vin blanc et du pain.","pron":"dü vẽ blã e dü pẽ","es":"Vino blanco y pan."},{"en":"Vous êtes de Paris?","pron":"vu zét dö parí","es":"¿Usted es de París?"},{"en":"Ça s'écrit comment?","pron":"sa sekrí komã","es":"¿Cómo se escribe?"}]},{"tipo":"clave","items":["<b>u</b> = ü (labios redondos) · <b>ou</b> = nuestra u.","Nasales: <i>an/en</i> (ã), <i>on</i> (õ), <i>in/ain</i> (ẽ); la n no se pronuncia.","Consonantes finales mudas, salvo a menudo c, r, f, l.","<b>Liaison</b>: <i>les amis, vous êtes, ils ont</i>. Pasa a la evaluación: necesitas 80%."]}],"c-frances-a1-m2-l1":[{"tipo":"texto","texto":"Los números del 0 al 69 son bastante lógicos. La sorpresa llega en el 70: los franceses dicen <b>sesenta y diez</b> (<i>soixante-dix</i>), el 80 es <b>cuatro veintes</b> (<i>quatre-vingts</i>) y el 90 es <b>cuatro veintes y diez</b> (<i>quatre-vingt-dix</i>). Suena a problema de matemáticas, pero con práctica sale solo. Otro detalle útil: en Francia los teléfonos se dictan <b>en pares</b>: 06 12 34 56 78 se dice «cero seis, doce, treinta y cuatro, cincuenta y seis, setenta y ocho»."},{"tipo":"tabla","titulo":"Del 0 al 20","voz":true,"colVoz":1,"encabezados":["Número","Francés","Se lee aprox."],"filas":[["0","zéro","zeró"],["1","un","ẽ"],["2","deux","dö"],["3","trois","truá"],["4","quatre","katr"],["5","cinq","sẽk"],["6","six","sis"],["7","sept","set"],["8","huit","üít"],["9","neuf","nöf"],["10","dix","dis"],["11","onze","õz"],["12","douze","duz"],["13","treize","trez"],["14","quatorze","katórz"],["15","quinze","kẽz"],["16","seize","sez"],["17","dix-sept","di-sét"],["18","dix-huit","di-züít"],["19","dix-neuf","diz-nöf"],["20","vingt","vẽ"]],"nota":"En <i>sept</i> la p no suena, y en <i>vingt</i> no suenan ni la g ni la t."},{"tipo":"tabla","titulo":"Las decenas y los números especiales","voz":true,"colVoz":1,"encabezados":["Número","Francés","Truco"],"filas":[["21","vingt et un","Con 1 se dice «y uno»: <i>vingt et un, trente et un…</i>"],["22","vingt-deux","Los demás, con guion"],["30","trente","trãt"],["40","quarante","karãt"],["50","cinquante","sẽkãt"],["60","soixante","suasãt"],["70","soixante-dix","60 + 10"],["71","soixante et onze","60 + 11"],["80","quatre-vingts","4 × 20"],["81","quatre-vingt-un","4 × 20 + 1 (sin <i>et</i> y sin s)"],["90","quatre-vingt-dix","4 × 20 + 10"],["99","quatre-vingt-dix-neuf","4 × 20 + 19"],["100","cent","sã"]],"nota":"En Bélgica y Suiza dicen <i>septante</i> (70) y <i>nonante</i> (90); en Suiza también <i>huitante</i> (80). En Francia y Quebec, lo de la tabla."},{"tipo":"escuchar","rotulo":"Escucha números reales","frases":[{"en":"Mon numéro, c'est le zéro six, douze, trente-quatre, cinquante-six, soixante-dix-huit.","es":"Mi número es el 06 12 34 56 78."},{"en":"Chambre quatre-vingt-quinze.","pron":"shãbr katr-vẽ-kẽz","es":"Habitación 95."},{"en":"Le bus soixante-douze.","pron":"lö büs suasãt-duz","es":"El camión 72."},{"en":"Ça fait vingt et un euros.","pron":"sa fé vẽ te ẽ nöró","es":"Son 21 euros."}]},{"tipo":"practica","rotulo":"¿Qué número es?","preguntas":[{"p":"<i>soixante-dix</i>","ops":["60","70","16"],"correcta":1},{"p":"<i>quatre-vingts</i>","ops":["24","80","84"],"correcta":1,"explica":"4 × 20 = 80."},{"p":"<i>quatre-vingt-dix-sept</i>","ops":["97","87","77"],"correcta":0,"explica":"4 × 20 + 17 = 97."},{"p":"¿Cómo se dice 21?","ops":["vingt-un","vingt et un","vingt-et-une"],"correcta":1},{"p":"¿Cómo se dice 75?","ops":["soixante-quinze","septante-cinq en Francia","soixante-cinq"],"correcta":0,"explica":"60 + 15. <i>Septante</i> es de Bélgica y Suiza."}]},{"tipo":"completar","rotulo":"Escribe el número en francés","voz":true,"items":[{"frase":"Mon numéro, c'est le zéro six, ___ (12), trente, quarante-cinq.","resp":["douze"],"es":"Mi número es el 06 12 30 45…"},{"frase":"J'habite au numéro ___ (15).","resp":["quinze"],"es":"Vivo en el número 15."},{"frase":"La chambre ___ (20), s'il vous plaît.","resp":["vingt"],"es":"La habitación 20, por favor."},{"frase":"Il y a ___ (60) minutes dans une heure.","resp":["soixante"],"es":"Hay 60 minutos en una hora."},{"frase":"Le train part du quai ___ (3).","resp":["trois"],"es":"El tren sale del andén 3."}]},{"tipo":"relacionar","rotulo":"Relaciona el número","voz":true,"pares":[["soixante-dix","70"],["quatre-vingts","80"],["quatre-vingt-dix","90"],["quinze","15"],["seize","16"],["cinquante","50"]]},{"tipo":"clave","items":["70 = <i>soixante-dix</i> (60 + 10) · 80 = <i>quatre-vingts</i> (4 × 20) · 90 = <i>quatre-vingt-dix</i>.","21, 31, 41… llevan <i>et</i>: <i>vingt et un</i>. 81 y 91, no.","En Francia los teléfonos se dictan en pares.","Bélgica y Suiza: <i>septante, nonante</i>."]}],"c-frances-a1-m2-l2":[{"tipo":"texto","texto":"<b>Avoir</b> significa «tener» y es el segundo verbo más usado del francés. Se usa para lo que tienes (<i>J'ai une voiture</i>) y, como en español, para la edad y para sensaciones: hambre, sed, frío, calor, miedo. La trampa está en la edad: el inglés dice «I am 30», pero el francés funciona como el español: <b>J'ai trente ans</b>. Recuerda que <i>je</i> se vuelve <b>j'</b> antes de vocal: <i>j'ai</i>, nunca «je ai»."},{"tipo":"tabla","titulo":"Avoir en presente","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español"],"filas":[["j'ai","yé","yo tengo"],["tu as","tü a","tú tienes"],["il a / elle a","il a / el a","él / ella tiene"],["on a","õ na","nosotros tenemos (informal)"],["nous avons","nu zavõ","nosotros tenemos"],["vous avez","vu zavé","usted tiene · ustedes tienen"],["ils ont / elles ont","il zõ / el zõ","ellos / ellas tienen"]],"nota":"Cuidado: <b>ils ont</b> (il zõ, con z: tienen) y <b>ils sont</b> (il sõ, con s: son) se distinguen solo por ese sonido."},{"tipo":"tabla","titulo":"Expresiones con avoir","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["J'ai trente ans.","Tengo treinta años."],["J'ai faim.","Tengo hambre."],["J'ai soif.","Tengo sed."],["J'ai froid. / J'ai chaud.","Tengo frío. / Tengo calor."],["J'ai sommeil.","Tengo sueño."],["J'ai besoin d'un taxi.","Necesito un taxi."],["J'ai mal à la tête.","Me duele la cabeza."]]},{"tipo":"comparar","titulo":"Con edad y sensaciones, siempre avoir","malTitulo":"Evita","mal":"<i>Je suis trente ans.</i><br><i>Je ai faim.</i><br><i>J'ai trente.</i>","bienTitulo":"Correcto","bien":"<i><b>J'ai</b> trente <b>ans</b>.</i> (la palabra <i>ans</i> es obligatoria)<br><i><b>J'ai</b> faim.</i><br><i>Quel âge <b>avez</b>-vous?</i>"},{"tipo":"dialogo","titulo":"Diálogo — Hora de la comida en la planta","lineas":[{"quien":"Thomas","en":"J'ai faim! On mange ensemble?","es":"¡Tengo hambre! ¿Comemos juntos?"},{"quien":"Lucía","en":"Oui, bonne idée. Tu as des enfants, Thomas?","es":"Sí, buena idea. ¿Tienes hijos, Thomas?"},{"quien":"Thomas","en":"Oui, j'ai deux filles. Elles ont huit et douze ans. Et toi?","es":"Sí, tengo dos hijas. Tienen ocho y doce años. ¿Y tú?"},{"quien":"Lucía","en":"Moi, j'ai un fils. Il a cinq ans. Et nous avons un chien!","es":"Yo tengo un hijo. Tiene cinco años. ¡Y tenemos un perro!"},{"quien":"Thomas","en":"Un chien? Il a quel âge?","es":"¿Un perro? ¿Cuántos años tiene?"},{"quien":"Lucía","en":"Il a trois ans. Il est très sympa!","es":"Tiene tres años. ¡Es muy buena onda!"}]},{"tipo":"practica","rotulo":"Elige la forma correcta","preguntas":[{"p":"«Tengo 25 años»","ops":["Je suis vingt-cinq ans.","J'ai vingt-cinq ans.","J'ai vingt-cinq."],"correcta":1},{"p":"Nous ___ une réunion à dix heures.","ops":["avez","avons","ont"],"correcta":1},{"p":"Mes parents ___ une maison à Oaxaca.","ops":["sont","ont","a"],"correcta":1,"explica":"«Tienen» = <b>ils ont</b>; <i>ils sont</i> es «son»."},{"p":"«Tengo frío»","ops":["Je suis froid.","J'ai froid.","J'ai le froid."],"correcta":1},{"p":"¿Cómo preguntas la edad a un cliente?","ops":["Quel âge avez-vous?","Combien ans vous êtes?","Vous êtes quel âge?"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa con avoir","voz":true,"items":[{"frase":"J'___ trente-deux ans.","resp":["ai"],"es":"Tengo treinta y dos años."},{"frase":"Tu ___ soif?","resp":["as"],"es":"¿Tienes sed?"},{"frase":"Vous ___ une chambre pour ce soir?","resp":["avez"],"es":"¿Tiene una habitación para esta noche?"},{"frase":"Elles ___ deux enfants.","resp":["ont"],"es":"Ellas tienen dos hijos."},{"frase":"Il ___ mal à la tête.","resp":["a"],"es":"Le duele la cabeza."}]},{"tipo":"clave","items":["<b>avoir</b>: <i>j'ai, tu as, il a, nous avons, vous avez, ils ont</i>.","Edad: <i>J'ai 30 <b>ans</b></i>, nunca <i>je suis</i>.","Hambre, sed, frío, calor, sueño: <i>j'ai faim, soif, froid, chaud, sommeil</i>.","<i>ils <b>ont</b></i> (z) = tienen · <i>ils <b>sont</b></i> (s) = son."]}],"c-frances-a1-m2-l3":[{"tipo":"texto","texto":"En francés, las nacionalidades y muchas profesiones cambian según sea hombre o mujer, y <b>a veces cambia también el sonido</b>: en <i>français</i> la s no suena, pero en <i>française</i> sí, y como z («franséz»). Los patrones más comunes: <b>+e</b> (<i>mexicain → mexicaine</i>), <b>-ien → -ienne</b> (<i>canadien → canadienne</i>), <b>-eur → -euse</b> (<i>serveur → serveuse</i>) y <b>-ier → -ière</b> (<i>infirmier → infirmière</i>). Y un detalle clave: con profesiones <b>no se usa artículo</b> después de <i>je suis</i>: <i>Je suis infirmière</i>, como en español «soy enfermera»."},{"tipo":"tabla","titulo":"Nacionalidades","voz":true,"colVoz":0,"encabezados":["Él / Ella","Español"],"filas":[["mexicain / mexicaine","mexicano / mexicana"],["français / française","francés / francesa"],["canadien / canadienne","canadiense"],["américain / américaine","estadounidense"],["espagnol / espagnole","español / española"],["colombien / colombienne","colombiano / colombiana"],["belge / belge","belga"],["suisse / suisse","suizo / suiza"]],"nota":"Las nacionalidades se escriben con <b>minúscula</b> como adjetivo (<i>Je suis mexicain</i>) y con mayúscula como persona (<i>les Mexicains</i>)."},{"tipo":"tabla","titulo":"Profesiones","voz":true,"colVoz":0,"encabezados":["Él / Ella","Español"],"filas":[["serveur / serveuse","mesero / mesera"],["vendeur / vendeuse","vendedor / vendedora"],["infirmier / infirmière","enfermero / enfermera"],["cuisinier / cuisinière","cocinero / cocinera"],["ingénieur / ingénieure","ingeniero / ingeniera"],["étudiant / étudiante","estudiante"],["comptable / comptable","contador / contadora"],["médecin / médecin","médico / médica"]]},{"tipo":"comparar","titulo":"Sin artículo con la profesión","malTitulo":"Evita","mal":"<i>Je suis une infirmière.</i><br><i>Il est un ingénieur.</i>","bienTitulo":"Correcto","bien":"<i>Je suis <b>infirmière</b>.</i><br><i>Il est <b>ingénieur</b>.</i> o <i><b>C'est un</b> ingénieur.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Feria de turismo en Guadalajara","lineas":[{"quien":"Sofía","en":"Bonjour! Vous êtes française?","es":"¡Buenos días! ¿Usted es francesa?"},{"quien":"Nathalie","en":"Non, je suis belge, de Bruxelles. Je suis agente de voyages.","es":"No, soy belga, de Bruselas. Soy agente de viajes."},{"quien":"Sofía","en":"Enchantée! Moi, je suis mexicaine. Je suis guide touristique à Guanajuato.","es":"¡Mucho gusto! Yo soy mexicana. Soy guía de turistas en Guanajuato."},{"quien":"Nathalie","en":"Super! Et votre collègue, il est guide aussi?","es":"¡Qué bien! ¿Y su compañero también es guía?"},{"quien":"Sofía","en":"Non, il est cuisinier. C'est le chef de notre restaurant.","es":"No, es cocinero. Es el chef de nuestro restaurante."}]},{"tipo":"practica","rotulo":"Masculino o femenino","preguntas":[{"p":"Camila es de Bogotá. <i>Elle est…</i>","ops":["colombien","colombienne","colombiane"],"correcta":1},{"p":"Mi hermana trabaja en un restaurante sirviendo mesas. <i>Elle est…</i>","ops":["serveuse","serveur","une serveuse"],"correcta":0,"explica":"Sin artículo después de <i>elle est</i>, y <b>-eur → -euse</b>."},{"p":"«Soy enfermero» (hombre)","ops":["Je suis un infirmier.","Je suis infirmière.","Je suis infirmier."],"correcta":2},{"p":"¿En cuál se pronuncia la consonante final?","ops":["français","anglais","japonais","française"],"correcta":3,"explica":"Sin <b>e</b> final la consonante no suena (anglé, japoné, franssé); con la <b>e</b> final, la s se pronuncia como z: «franséz»."},{"p":"Una persona de Estados Unidos es…","ops":["estadounien","américaine / américain","étatsunienne"],"correcta":1}]},{"tipo":"relacionar","rotulo":"Relaciona la profesión","voz":true,"pares":[["vendeuse","vendedora"],["cuisinier","cocinero"],["comptable","contador"],["infirmière","enfermera"],["étudiant","estudiante"],["serveur","mesero"]]},{"tipo":"pronunciar","rotulo":"Escucha el cambio y repítelo","frases":[{"en":"Il est français. Elle est française.","pron":"il é frãsé. el é frãséz","es":"Él es francés. Ella es francesa."},{"en":"Il est canadien. Elle est canadienne.","pron":"il é kanadiẽ. el é kanadién","es":"Él es canadiense. Ella es canadiense."},{"en":"Je suis serveuse dans un café.","pron":"yö süí servöz dã zẽ kafé","es":"Soy mesera en un café."},{"en":"Vous faites quoi dans la vie?","pron":"vu fet kuá dã la ví","es":"¿A qué se dedica?"}]},{"tipo":"clave","items":["Femenino: <b>+e</b>, <b>-ienne</b>, <b>-euse</b>, <b>-ière</b>; a veces cambia el sonido.","Con <i>je suis / il est</i> + profesión, <b>sin artículo</b>.","Para preguntar la profesión: <i>Vous faites quoi dans la vie?</i>","Nacionalidad con minúscula: <i>Je suis mexicaine</i>."]}],"c-frances-a1-m2-l4":[{"tipo":"texto","texto":"Como en español, en francés todo sustantivo es masculino o femenino. Los artículos son: <b>un / une / des</b> (un, una, unos) y <b>le / la / les</b> (el, la, los, las). Antes de vocal o h, <i>le</i> y <i>la</i> se vuelven <b>l'</b>: <i>l'hôtel, l'école</i>. Y un detalle importantísimo: la s del plural casi nunca suena, así que <b>el artículo es lo que te dice si es plural</b>: <i>le livre</i> (lö) y <i>les livres</i> (le) solo se distinguen por el artículo."},{"tipo":"tabla","titulo":"Los artículos en acción","voz":true,"colVoz":0,"encabezados":["Francés","Español","Tipo"],"filas":[["un bureau","una oficina / un escritorio","masculino"],["une voiture","un coche","femenino"],["des amis","(unos) amigos","plural"],["le train","el tren","masculino"],["la gare","la estación de tren","femenino"],["l'hôtel","el hotel","antes de vocal o h"],["l'école","la escuela","antes de vocal"],["les enfants","los niños","plural (con liaison: le zãfã)"]],"nota":"<b>des</b> no se puede omitir: «tengo amigos en Lyon» = <i>J'ai <b>des</b> amis à Lyon</i>."},{"tipo":"comparar","titulo":"Mismo objeto, otro género","malTitulo":"En español","mal":"<b>la</b> leche · <b>la</b> sal · <b>el</b> diente · <b>la</b> nariz · <b>el</b> color · <b>el</b> equipo · <b>la</b> sangre","bienTitulo":"En francés","bien":"<b>le</b> lait · <b>le</b> sel · <b>la</b> dent · <b>le</b> nez · <b>la</b> couleur · <b>l'</b>équipe (fem.) · <b>le</b> sang"},{"tipo":"tarjetas","rotulo":"Aprende la palabra con su artículo","voz":true,"vozEn":"reverso","instruccion":"Ves la palabra en español; di la palabra en francés con su artículo antes de voltear.","tarjetas":[{"frente":"la leche","reverso":"le lait","ej":"Un café au lait."},{"frente":"el coche","reverso":"la voiture","ej":"La voiture est rouge."},{"frente":"el color","reverso":"la couleur","ej":"Quelle couleur?"},{"frente":"el equipo","reverso":"l'équipe","ej":"L'équipe est prête."},{"frente":"la sal","reverso":"le sel","ej":"Le sel, s'il vous plaît."},{"frente":"el diente","reverso":"la dent","ej":"J'ai mal à la dent."}]},{"tipo":"practica","rotulo":"Elige el artículo","preguntas":[{"p":"___ hôtel est près de la plage.","ops":["Le","La","L'"],"correcta":2,"explica":"Antes de vocal o h muda: <b>l'</b>."},{"p":"J'ai ___ amis à Montréal.","ops":["les","des","un"],"correcta":1,"explica":"«Tengo amigos» (no específicos) = <b>des</b>."},{"p":"«La leche» en francés es…","ops":["la lait","le lait","les lait"],"correcta":1},{"p":"¿Cómo sabes al oírlo que <i>les livres</i> es plural?","ops":["Por la s de livres","Por el artículo les","Por la e final"],"correcta":1},{"p":"Una voiture, ___ voiture. (el artículo definido)","ops":["le","la","un"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa con el artículo","voz":true,"items":[{"frase":"J'ai ___ frères et une sœur.","resp":["des"],"es":"Tengo hermanos y una hermana."},{"frase":"___ hôtel est très grand.","resp":["L'","L"],"es":"El hotel es muy grande."},{"frase":"C'est ___ voiture de Marc.","resp":["la"],"es":"Es el coche de Marc."},{"frase":"Je cherche ___ banque.","resp":["une"],"es":"Busco un banco."},{"frase":"___ enfants sont à l'école.","resp":["Les"],"es":"Los niños están en la escuela."}]},{"tipo":"clave","items":["<b>un / une / des</b> · <b>le / la / l' / les</b>.","<b>des</b> es obligatorio en plural: <i>J'ai des amis</i>.","El artículo te dice si es plural; la s casi nunca suena.","Aprende cada palabra con su artículo: <i>le lait, la voiture, la couleur</i>."]}],"c-frances-a1-m2-l5":[{"tipo":"texto","texto":"Hay tres formas de hacer una pregunta de sí o no en francés, de la más relajada a la más formal: <b>1) entonación</b>: subes la voz al final (<i>Vous êtes mexicain?</i>); <b>2) est-ce que</b> al inicio (<i>Est-ce que vous êtes mexicain?</i>), muy común y fácil; <b>3) inversión</b>: verbo antes del pronombre con guion (<i>Êtes-vous mexicain?</i>), típica de lo escrito y lo formal. Para preguntas de información agregas una palabra interrogativa."},{"tipo":"tabla","titulo":"Palabras para preguntar","voz":true,"colVoz":1,"encabezados":["Palabra","Ejemplo","Español"],"filas":[["comment","Comment vous appelez-vous?","¿Cómo se llama?"],["où","Où est-ce que vous habitez?","¿Dónde vive?"],["quel / quelle","Quel est votre numéro de téléphone?","¿Cuál es su número de teléfono?"],["quel âge","Quel âge avez-vous?","¿Cuántos años tiene?"],["quand","Quand est-ce que vous commencez?","¿Cuándo empieza?"],["combien","Combien de langues parlez-vous?","¿Cuántos idiomas habla?"],["qu'est-ce que","Qu'est-ce que vous faites?","¿Qué hace? / ¿A qué se dedica?"]],"nota":"<b>quel</b> (masculino) y <b>quelle</b> (femenino) suenan igual: <i>quel numéro, quelle adresse</i>."},{"tipo":"dialogo","titulo":"Diálogo — Entrevista en un call center de Monterrey con clientes de Francia","lineas":[{"quien":"Sophie","en":"Bonjour. Asseyez-vous, s'il vous plaît. Comment vous appelez-vous?","es":"Buenos días. Siéntese, por favor. ¿Cómo se llama?"},{"quien":"Mariana","en":"Je m'appelle Mariana Torres.","es":"Me llamo Mariana Torres."},{"quien":"Sophie","en":"Torres, ça s'écrit comment?","es":"Torres, ¿cómo se escribe?"},{"quien":"Mariana","en":"T, O, deux R, E, S.","es":"T, O, doble R, E, S."},{"quien":"Sophie","en":"Merci. Quel âge avez-vous?","es":"Gracias. ¿Cuántos años tiene?"},{"quien":"Mariana","en":"J'ai vingt-six ans.","es":"Tengo veintiséis años."},{"quien":"Sophie","en":"Et quelle est votre adresse e-mail?","es":"¿Y cuál es su correo electrónico?"},{"quien":"Mariana","en":"C'est mariana point torres arobase gmail point com.","es":"Es mariana punto torres arroba gmail punto com."}]},{"tipo":"comparar","titulo":"«¿Cuál es…?» se dice con quel","malTitulo":"Evita","mal":"<i>Qu'est-ce que est votre nom?</i><br><i>Quoi est votre numéro?</i>","bienTitulo":"Correcto","bien":"<i><b>Quel</b> est votre numéro?</i><br><i><b>Quelle</b> est votre adresse?</i><br>Para el nombre: <i>Comment vous appelez-vous?</i>"},{"tipo":"practica","rotulo":"Elige la palabra interrogativa","preguntas":[{"p":"___ habitez-vous? — À Puebla.","ops":["Où","Quand","Comment"],"correcta":0},{"p":"___ est votre profession?","ops":["Quel","Quelle","Qu'est-ce que"],"correcta":1,"explica":"<i>profession</i> es femenino → <b>quelle</b>."},{"p":"___ d'enfants avez-vous? — Deux.","ops":["Quel","Combien","Où"],"correcta":1},{"p":"¿Cuál es la pregunta más formal?","ops":["Vous êtes marié?","Est-ce que vous êtes marié?","Êtes-vous marié?"],"correcta":2,"explica":"La inversión (<i>Êtes-vous…</i>) es la más formal."},{"p":"En un correo, «@» se dice…","ops":["arrobe","arobase","at"],"correcta":1}]},{"tipo":"ordenar","rotulo":"Arma la pregunta","voz":true,"items":[{"frase":"Où est-ce que vous habitez?","es":"¿Dónde vive usted?"},{"frase":"Quel âge avez-vous?","es":"¿Cuántos años tiene?"},{"frase":"Est-ce que vous parlez anglais?","es":"¿Habla usted inglés?"},{"frase":"Quelle est votre adresse e-mail?","es":"¿Cuál es su correo electrónico?"}]},{"tipo":"escuchar","rotulo":"Escucha y repite las preguntas","frases":[{"en":"Quel âge avez-vous?","pron":"kel ash avé vu","es":"¿Cuántos años tiene?"},{"en":"Où est-ce que vous habitez?","pron":"u és kö vu zabité","es":"¿Dónde vive?"},{"en":"Qu'est-ce que vous faites?","pron":"kés kö vu fet","es":"¿A qué se dedica?"},{"en":"Vous parlez français?","pron":"vu parlé frãsé","es":"¿Habla francés?"}]},{"tipo":"reflexion","rotulo":"Tu ficha en francés","pregunta":"Contesta por escrito estas preguntas con tus datos reales (o inventados): Comment vous appelez-vous? Quel âge avez-vous? Vous êtes d'où? Où est-ce que vous habitez? Qu'est-ce que vous faites? Quel est votre numéro de téléphone? Después léelas en voz alta.","ayuda":"Je m'appelle… J'ai … ans. Je suis de… J'habite à… Je suis … (profession). Mon numéro, c'est le…"},{"tipo":"clave","items":["Sí o no: entonación, <i>est-ce que…</i> o inversión (<i>Êtes-vous…?</i>).","<i>comment, où, quel/quelle, quand, combien, qu'est-ce que</i>.","«¿Cuál es…?» = <i>Quel(le) est…?</i>","@ = <i>arobase</i> · punto = <i>point</i>. Pasa a la evaluación: necesitas 80%."]}],"c-frances-a1-m3-l1":[{"tipo":"texto","texto":"Buenas noticias: <b>casi 9 de cada 10 verbos franceses terminan en -er</b> y se conjugan igual. Quitas <i>-er</i> y agregas <b>-e, -es, -e, -ons, -ez, -ent</b>. Y mejor aún: <i>je parle, tu parles, il parle</i> e <i>ils parlent</i> <b>se pronuncian exactamente igual</b> («parl»). La s y el famoso <i>-ent</i> del plural no suenan. Solo <i>nous</i> (-ons, «õ») y <i>vous</i> (-ez, «é») tienen un sonido distinto. Por eso el pronombre es obligatorio: es lo único que te dice quién hace la acción."},{"tipo":"tabla","titulo":"Parler (hablar) en presente","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español"],"filas":[["je parle","yö parl","yo hablo"],["tu parles","tü parl","tú hablas"],["il / elle / on parle","il parl","él / ella habla · nosotros hablamos"],["nous parlons","nu parlõ","nosotros hablamos"],["vous parlez","vu parlé","usted habla · ustedes hablan"],["ils / elles parlent","il parl","ellos / ellas hablan"]],"nota":"Con verbos que empiezan con vocal o h hay <i>j'</i> y <i>liaison</i>: <i>j'habite, nous habitons</i> (nu zabitõ), <i>vous habitez</i> (vu zabité). Dos detalles de escritura: <i>nous mang<b>e</b>ons</i> y <i>nous commen<b>ç</b>ons</i>, para que la g y la c no cambien de sonido."},{"tipo":"tabla","titulo":"Verbos en -er de todos los días","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["travailler","trabajar"],["habiter","vivir (en un lugar)"],["manger","comer"],["écouter","escuchar"],["regarder","ver, mirar"],["étudier","estudiar"],["commencer","empezar"],["terminer","terminar"],["cuisiner","cocinar"],["rester","quedarse"]]},{"tipo":"comparar","titulo":"Falsos amigos: verbos que engañan","malTitulo":"Parece que significa","mal":"<i>rester</i> = restar<br><i>regarder</i> = guardar<br><i>quitter</i> = quitar<br><i>tirer</i> = tirar (a la basura)","bienTitulo":"En realidad significa","bien":"<i><b>rester</b></i> = quedarse: <i>Je reste à la maison.</i><br><i><b>regarder</b></i> = mirar, ver: <i>Je regarde la télé.</i> (guardar = <i>ranger</i>)<br><i><b>quitter</b></i> = irse de, dejar: <i>Je quitte le bureau à six heures.</i> (quitar = <i>enlever</i>)<br><i><b>tirer</b></i> = jalar (lo verás en las puertas: <i>Tirez</i>). Tirar a la basura = <i>jeter</i>."},{"tipo":"dialogo","titulo":"Diálogo — Videollamada con una colega de Lyon","lineas":[{"quien":"Élodie","en":"Tu parles bien français! Tu étudies où?","es":"¡Hablas bien francés! ¿Dónde estudias?"},{"quien":"Iván","en":"Merci! J'étudie en ligne, le soir. Je travaille dans un centre d'appels à Monterrey.","es":"¡Gracias! Estudio en línea, en la noche. Trabajo en un call center en Monterrey."},{"quien":"Élodie","en":"Tu travailles avec des clients français?","es":"¿Trabajas con clientes franceses?"},{"quien":"Iván","en":"Oui, et avec des clients belges aussi. On parle avec des clients toute la journée.","es":"Sí, y también con clientes belgas. Hablamos con clientes todo el día."},{"quien":"Élodie","en":"Et le soir, tu restes à la maison?","es":"¿Y en la noche te quedas en casa?"},{"quien":"Iván","en":"Oui, je regarde des séries et je cuisine un peu.","es":"Sí, veo series y cocino un poco."}]},{"tipo":"practica","rotulo":"Elige la forma correcta","preguntas":[{"p":"Nous ___ espagnol et français.","ops":["parlons","parlez","parlent"],"correcta":0},{"p":"¿Cómo se pronuncia <i>ils travaillent</i>?","ops":["«il travayént», con -ent","«il traváy»: -ent no suena","«il travayã», con nasal"],"correcta":1,"explica":"La terminación <b>-ent</b> de los verbos nunca se pronuncia."},{"p":"«Me quedo en el hotel»","ops":["Je regarde l'hôtel.","Je quitte l'hôtel.","Je reste à l'hôtel."],"correcta":2,"explica":"<b>rester</b> = quedarse; <i>quitter</i> = irse de."},{"p":"Vous ___ où? — À Puebla.","ops":["habitons","habitez","habite"],"correcta":1},{"p":"Nous ___ à huit heures. (commencer)","ops":["commençons","commencons","commenceons"],"correcta":0,"explica":"Con <i>nous</i> se escribe <b>ç</b> para que suene «s»."}]},{"tipo":"completar","rotulo":"Conjuga el verbo","voz":true,"items":[{"frase":"Je ___ dans un hôtel. (travailler)","resp":["travaille"],"es":"Trabajo en un hotel."},{"frase":"Tu ___ anglais? (parler)","resp":["parles"],"es":"¿Hablas inglés?"},{"frase":"Nous ___ à Mérida. (habiter)","resp":["habitons"],"es":"Vivimos en Mérida."},{"frase":"Vous ___ la télé le soir? (regarder)","resp":["regardez"],"es":"¿Ve la tele en la noche?"},{"frase":"Ils ___ au restaurant. (manger)","resp":["mangent"],"es":"Comen en el restaurante."},{"frase":"Nous ___ à midi. (manger)","resp":["mangeons"],"es":"Comemos a mediodía."}]},{"tipo":"pronunciar","rotulo":"Dilo en voz alta","frases":[{"en":"Je parle un peu français.","pron":"yö parl ẽ pö frãsé","es":"Hablo un poco de francés."},{"en":"Nous travaillons le samedi.","pron":"nu travayõ lö samdí","es":"Trabajamos los sábados."},{"en":"Vous habitez où?","pron":"vu zabité u","es":"¿Dónde vive usted?"},{"en":"Ils mangent au restaurant.","pron":"il mãy o restorã","es":"Comen en el restaurante."},{"en":"Tu regardes la télé?","pron":"tü rögárd la telé","es":"¿Ves la tele?"}]},{"tipo":"clave","items":["Verbos en <b>-er</b>: <i>-e, -es, -e, -ons, -ez, -ent</i>.","<i>parle, parles, parlent</i> suenan igual; solo <i>nous</i> y <i>vous</i> cambian.","<i>nous mangeons, nous commençons</i>.","Falsos amigos: <i>rester</i> = quedarse, <i>regarder</i> = mirar, <i>quitter</i> = irse de."]}],"c-frances-a1-m3-l2":[{"tipo":"texto","texto":"Para preguntar la hora: <b>Quelle heure est-il?</b> Y para contestar siempre se usa <b>Il est…</b> + número + <b>heure(s)</b>, aunque sean las dos o las diez (nunca «ils sont»). La palabra <i>heure</i> no se puede quitar: <i>Il est cinq heures</i>. Para los cuartos y las medias: <b>et quart</b> (y cuarto), <b>et demie</b> (y media) y <b>moins le quart</b> (cuarto para). En horarios oficiales (trenes, tiendas, citas, juntas) los franceses usan el <b>reloj de 24 horas</b>: <i>dix-sept heures trente</i> (17:30). Y verás la hora escrita así: <b>17 h 30</b>."},{"tipo":"tabla","titulo":"La hora en francés","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español"],"filas":[["Il est une heure.","il é ün ör","Es la una."],["Il est deux heures.","il é dö zör","Son las dos."],["Il est trois heures et quart.","il é truá zör e kar","Son las tres y cuarto."],["Il est quatre heures et demie.","il é katr ör e dmí","Son las cuatro y media."],["Il est cinq heures moins le quart.","il é sẽ kör muẽ lö kar","Son cuarto para las cinco."],["Il est six heures dix.","il é si zör dis","Son las seis y diez."],["Il est sept heures moins dix.","il é set ör muẽ dis","Son diez para las siete."],["Il est midi.","il é midí","Son las doce del día."],["Il est minuit.","il é minüí","Es medianoche."]],"nota":"Fíjate en la <i>liaison</i>: <i>deux heures</i> (dö zör), <i>trois heures</i> (truá zör), <i>six heures</i> (si zör), <i>dix heures</i> (di zör). Para aclarar la parte del día: <i>du matin</i> (de la mañana), <i>de l'après-midi</i> (de la tarde), <i>du soir</i> (de la noche)."},{"tipo":"comparar","titulo":"«Son las…» no se traduce palabra por palabra","malTitulo":"Evita","mal":"<i>Sont deux heures.</i><br><i>Il est une.</i><br><i>À les huit heures.</i>","bienTitulo":"Correcto","bien":"<i><b>Il est</b> deux heures.</i> (siempre <i>il est</i>, en singular)<br><i>Il est une <b>heure</b>.</i> (<i>heure</i> es femenino: <i>une</i>)<br><i><b>À</b> huit heures.</i> (a las ocho)"},{"tipo":"dialogo","titulo":"Diálogo — Llamada de Ciudad de México a París","lineas":[{"quien":"Andrea","en":"Bonjour, monsieur Petit. Vous avez cinq minutes?","es":"Buenos días, señor Petit. ¿Tiene cinco minutos?"},{"quien":"M. Petit","en":"Oui, mais vite: ici, il est dix-huit heures et je termine à dix-huit heures trente.","es":"Sí, pero rápido: aquí son las seis de la tarde y salgo a las seis y media."},{"quien":"Andrea","en":"Ah, ici il est seulement dix heures du matin!","es":"¡Ah, aquí apenas son las diez de la mañana!"},{"quien":"M. Petit","en":"On organise une réunion demain?","es":"¿Organizamos una junta mañana?"},{"quien":"Andrea","en":"Oui, bonne idée. À quelle heure?","es":"Sí, buena idea. ¿A qué hora?"},{"quien":"M. Petit","en":"À seize heures, heure de Paris. Donc à huit heures pour vous.","es":"A las cuatro de la tarde, hora de París. O sea, a las ocho para usted."},{"quien":"Andrea","en":"Parfait. À demain, monsieur!","es":"Perfecto. ¡Hasta mañana, señor!"}]},{"tipo":"practica","rotulo":"¿Qué hora es?","preguntas":[{"p":"<i>Il est trois heures et demie.</i>","ops":["3:15","3:30","2:30"],"correcta":1},{"p":"<i>Il est cinq heures moins le quart.</i>","ops":["5:15","5:45","4:45"],"correcta":2,"explica":"<b>moins le quart</b> = cuarto para: se dice la hora siguiente."},{"p":"«Es la una»","ops":["Il est une heure.","Il est un.","Il est un heure."],"correcta":0,"explica":"<i>heure</i> es femenino: <b>une heure</b>."},{"p":"En la estación ves <i>Départ : 19 h 20</i>. El anuncio dice…","ops":["dix-neuf et vingt","neuf heures vingt","dix-neuf heures vingt"],"correcta":2},{"p":"«¿A qué hora empieza la junta?»","ops":["Quelle heure commence la réunion?","À quelle heure commence la réunion?","À quelle heure est la réunion commence?"],"correcta":1}]},{"tipo":"relacionar","rotulo":"Relaciona cada hora","voz":true,"pares":[["midi","12:00 del día"],["minuit","12:00 de la noche"],["huit heures et quart","8:15"],["neuf heures moins le quart","8:45"],["dix heures et demie","10:30"],["vingt heures","20:00"]]},{"tipo":"completar","rotulo":"Completa la hora","voz":true,"items":[{"frase":"Il est sept heures et ___. (7:30)","resp":["demie"],"es":"Son las siete y media."},{"frase":"Il est dix heures moins le ___. (9:45)","resp":["quart"],"es":"Son cuarto para las diez."},{"frase":"À ___ heure commence le film?","resp":["quelle"],"es":"¿A qué hora empieza la película?"},{"frase":"Je commence ___ huit heures.","resp":["à"],"es":"Empiezo a las ocho."},{"frase":"Il est ___. (12:00 de la noche)","resp":["minuit"],"es":"Es medianoche."}]},{"tipo":"clave","items":["<i>Quelle heure est-il?</i> — <i><b>Il est</b> deux <b>heures</b>.</i>","<i>et quart</i> (:15), <i>et demie</i> (:30), <i>moins le quart</i> (cuarto para).","<i>midi</i> = 12 del día · <i>minuit</i> = medianoche.","Horarios oficiales con 24 horas: <i>dix-neuf heures vingt</i> (19 h 20)."]}],"c-frances-a1-m3-l3":[{"tipo":"texto","texto":"Para la rutina necesitas los <b>verbos pronominales</b>, que son como nuestros «me levanto, me baño, me acuesto»: <i>je <b>me</b> lève, je <b>me</b> douche, je <b>me</b> couche</i>. El pronombre cambia con la persona: <b>me, te, se, nous, vous, se</b>. Antes de vocal, <i>me</i> se vuelve <b>m'</b>: <i>je m'habille</i> (me visto). También te sirve <b>prendre</b> (tomar), que es irregular: <i>je prends le bus, je prends le petit-déjeuner</i>."},{"tipo":"tabla","titulo":"Se lever (levantarse)","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español"],"filas":[["je me lève","yö mö lév","yo me levanto"],["tu te lèves","tü tö lév","tú te levantas"],["il / elle se lève","il sö lév","él / ella se levanta"],["nous nous levons","nu nu lövõ","nosotros nos levantamos"],["vous vous levez","vu vu lövé","usted se levanta · ustedes se levantan"],["ils / elles se lèvent","il sö lév","ellos / ellas se levantan"]],"nota":"El acento grave aparece solo cuando la terminación no suena: <i>je me l<b>è</b>ve</i>, pero <i>nous nous levons</i>."},{"tipo":"tabla","titulo":"Un día normal","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["Je me réveille à six heures.","Me despierto a las seis."],["Je me lève tout de suite.","Me levanto de inmediato."],["Je me douche et je m'habille.","Me baño y me visto."],["Je prends le petit-déjeuner.","Desayuno."],["Je prends le bus à sept heures.","Tomo el camión a las siete."],["Je déjeune à la cantine.","Como (al mediodía) en el comedor."],["Je rentre à la maison vers dix-huit heures.","Regreso a casa como a las seis de la tarde."],["Je dîne avec ma famille.","Ceno con mi familia."],["Je me couche vers onze heures.","Me acuesto como a las once."]],"nota":"<b>vers</b> = «como a», «alrededor de». <b>rentrer</b> = regresar a casa (entrar es <i>entrer</i>)."},{"tipo":"comparar","titulo":"Déjeuner no es desayunar","malTitulo":"En México","mal":"<b>desayuno</b> (7 a 9 a. m.)<br><b>comida</b> (2 a 4 p. m.)<br><b>cena</b> (8 a 10 p. m.)","bienTitulo":"En Francia","bien":"<b>le petit-déjeuner</b> (7 a 9 h)<br><b>le déjeuner</b> (12 a 14 h): ¡es la comida del mediodía!<br><b>le dîner</b> (19 a 21 h)<br>Ojo: en <b>Quebec</b>, Bélgica y Suiza dicen <i>déjeuner</i> (desayuno), <i>dîner</i> (comida) y <i>souper</i> (cena)."},{"tipo":"dialogo","titulo":"Diálogo — Turnos en una planta automotriz de Silao","lineas":[{"quien":"M. Dubois","en":"Vous commencez à quelle heure, Ricardo?","es":"¿A qué hora empieza, Ricardo?"},{"quien":"Ricardo","en":"Je commence à six heures du matin. Je me lève à quatre heures et demie!","es":"Empiezo a las seis de la mañana. ¡Me levanto a las cuatro y media!"},{"quien":"M. Dubois","en":"Oh là là! Et vous déjeunez à quelle heure?","es":"¡Híjole! ¿Y a qué hora come?"},{"quien":"Ricardo","en":"À onze heures, à la cantine. Je termine à quatorze heures.","es":"A las once, en el comedor. Salgo a las dos de la tarde."},{"quien":"M. Dubois","en":"Et l'après-midi?","es":"¿Y en la tarde?"},{"quien":"Ricardo","en":"Je rentre à la maison, je mange avec ma famille et je me repose.","es":"Regreso a casa, como con mi familia y descanso."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"Je ___ à six heures. (se lever)","ops":["me lève","se lève","lève"],"correcta":0},{"p":"Nous ___ tard le dimanche. (se coucher)","ops":["se couchons","nous couchons","couchons"],"correcta":1},{"p":"Estás en París. ¿Cómo se llama la comida de la 1 de la tarde?","ops":["le petit-déjeuner","le dîner","le déjeuner"],"correcta":2},{"p":"«Me baño» (en regadera)","ops":["Je douche.","Je me douche.","Je suis douche."],"correcta":1},{"p":"<i>Je rentre à la maison</i> significa…","ops":["Regreso a casa.","Entro a la casa.","Rento una casa."],"correcta":0,"explica":"<b>rentrer</b> = regresar (a casa)."}]},{"tipo":"ordenar","rotulo":"Arma tu rutina","voz":true,"items":[{"frase":"Je me lève à six heures","es":"Me levanto a las seis"},{"frase":"Je prends le bus à sept heures","es":"Tomo el camión a las siete"},{"frase":"Le soir je dîne avec ma famille","es":"En la noche ceno con mi familia"},{"frase":"Je me couche vers onze heures","es":"Me acuesto como a las once"}]},{"tipo":"pronunciar","rotulo":"Cuenta tu día en voz alta","frases":[{"en":"Je me réveille à six heures.","pron":"yö mö revéi a si zör","es":"Me despierto a las seis."},{"en":"Je prends le petit-déjeuner.","pron":"yö prã lö pti deyöné","es":"Desayuno."},{"en":"Je me couche vers minuit.","pron":"yö mö kush ver minüí","es":"Me acuesto como a medianoche."},{"en":"Nous dînons à vingt heures.","pron":"nu dinõ a vẽ tör","es":"Cenamos a las ocho de la noche."}]},{"tipo":"clave","items":["Pronominales: <i>je me lève, tu te lèves, il se lève, nous nous levons…</i>","<i>petit-déjeuner</i> = desayuno · <i>déjeuner</i> = comida del mediodía · <i>dîner</i> = cena (en Francia).","<i>rentrer</i> = regresar a casa · <i>vers</i> = como a.","<i>je prends</i> = tomo: <i>le bus, le petit-déjeuner</i>."]}],"c-frances-a1-m3-l4":[{"tipo":"texto","texto":"Los días y los meses se escriben <b>con minúscula</b>, igual que en español. Para las fechas, el francés es más corto que nosotros: <b>le</b> + número + mes, <b>sin «de»</b>: <i>le seize septembre</i> (el 16 de septiembre). Solo el día 1 es especial: <i>le <b>premier</b> mai</i>. Y ojo con los días: <b>lundi</b> sin artículo es «el lunes» (este lunes concreto), mientras que <b>le lundi</b> significa «los lunes», cada semana. Justo al revés de lo que te dice el oído."},{"tipo":"tabla","titulo":"Los días de la semana","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español"],"filas":[["lundi","lẽdí","lunes"],["mardi","mardí","martes"],["mercredi","merkrödí","miércoles"],["jeudi","yödí","jueves"],["vendredi","vãdrödí","viernes"],["samedi","samdí","sábado"],["dimanche","dimãsh","domingo"],["le week-end","lö uikénd","el fin de semana"]]},{"tipo":"tabla","titulo":"Los meses del año","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español"],"filas":[["janvier","yãvié","enero"],["février","fevrié","febrero"],["mars","mars","marzo"],["avril","avríl","abril"],["mai","mé","mayo"],["juin","yüẽ","junio"],["juillet","yüié","julio"],["août","ut","agosto"],["septembre","septãbr","septiembre"],["octobre","októbr","octubre"],["novembre","novãbr","noviembre"],["décembre","desãbr","diciembre"]],"nota":"«En agosto» = <i><b>en</b> août</i>. Cuidado con <b>juin</b> (nasal: yüẽ) y <b>juillet</b> (yüié): son los que más se confunden al oído."},{"tipo":"comparar","titulo":"Las fechas, al estilo francés","malTitulo":"Evita","mal":"<i>Le cinq de mai.</i><br><i>Le un janvier.</i><br><i>Lundi, Mardi, Janvier</i> con mayúscula","bienTitulo":"Correcto","bien":"<i>Le <b>cinq mai</b>.</i> (sin «de»)<br><i>Le <b>premier</b> janvier.</i> (solo el día 1 lleva ordinal)<br><i>lundi, mardi, janvier</i>, con minúscula"},{"tipo":"escuchar","rotulo":"Escucha y repite","frases":[{"en":"On est quel jour, aujourd'hui?","pron":"õ né kel yur oyurdüí","es":"¿Qué día es hoy?"},{"en":"Aujourd'hui, on est vendredi.","pron":"oyurdüí õ né vãdrödí","es":"Hoy es viernes."},{"en":"Mon anniversaire, c'est le premier juin.","pron":"mõ nanivérsér sé lö prömié yüẽ","es":"Mi cumpleaños es el primero de junio."},{"en":"Le quatorze juillet, c'est la fête nationale.","pron":"lö katórz yüié sé la fet nasionál","es":"El 14 de julio es la fiesta nacional (de Francia)."},{"en":"Au Mexique, le Jour des morts, c'est le deux novembre.","es":"En México, el Día de Muertos es el 2 de noviembre."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«El 16 de septiembre»","ops":["le seize de septembre","le seize septembre","la seize septembre"],"correcta":1},{"p":"«El 1.º de mayo»","ops":["le premier mai","le un mai","le première mai"],"correcta":0},{"p":"<i>Le samedi, je travaille.</i> significa…","ops":["Este sábado trabajo.","El sábado pasado trabajé.","Los sábados trabajo."],"correcta":2,"explica":"<b>le</b> + día = cada semana. Sin artículo = ese día concreto."},{"p":"¿Qué mes se confunde fácilmente con <i>juin</i>?","ops":["janvier","juillet","août"],"correcta":1},{"p":"«En agosto»","ops":["à août","dans août","en août"],"correcta":2}]},{"tipo":"completar","rotulo":"Completa la fecha","voz":true,"items":[{"frase":"Aujourd'hui, on est ___. (lunes)","resp":["lundi"],"es":"Hoy es lunes."},{"frase":"Mon anniversaire, c'est le ___ mars. (1.º)","resp":["premier"],"es":"Mi cumpleaños es el primero de marzo."},{"frase":"Nous partons en vacances en ___. (julio)","resp":["juillet"],"es":"Nos vamos de vacaciones en julio."},{"frase":"___ samedi, je joue au foot. (los sábados)","resp":["Le"],"es":"Los sábados juego futbol."},{"frase":"Noël, c'est le vingt-cinq ___. (diciembre)","resp":["décembre","decembre"],"es":"Navidad es el 25 de diciembre."}]},{"tipo":"clave","items":["Días y meses con minúscula.","Fechas sin «de»: <i>le seize septembre</i>; el día 1: <i>le premier</i>.","<i>lundi</i> = este lunes · <i>le lundi</i> = los lunes.","<i>en août, en juillet</i>; no confundas <i>juin</i> y <i>juillet</i>."]}],"c-frances-a1-m3-l5":[{"tipo":"texto","texto":"En español decimos «me gusta el café» (el café es el sujeto). En francés es al revés y más sencillo: <b>j'aime le café</b>, «yo amo el café». Los verbos de gusto van del más fuerte al más suave: <i>adorer</i>, <i>aimer beaucoup</i>, <i>aimer bien</i>, <i>ne pas aimer</i>, <i>détester</i>. Después va un sustantivo con <b>le, la, les</b> o directamente un verbo en infinitivo: <i>J'aime cuisiner</i>. Para negar, el verbo queda en medio de <b>ne… pas</b>: <i>Je <b>ne</b> parle <b>pas</b> allemand</i>."},{"tipo":"tabla","titulo":"De «me encanta» a «lo odio»","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["J'adore danser.","Me encanta bailar."],["J'aime beaucoup le cinéma.","Me gusta mucho el cine."],["J'aime bien le sport.","Me gusta el deporte."],["Je préfère le thé.","Prefiero el té."],["Je n'aime pas le café.","No me gusta el café."],["Je n'aime pas du tout le froid.","No me gusta nada el frío."],["Je déteste attendre.","Odio esperar."],["Et toi, tu aimes le foot?","¿Y a ti te gusta el futbol?"]],"nota":"<i>préférer</i> cambia el acento: <i>je préf<b>è</b>re</i> (yö prefér), <i>nous préférons</i>."},{"tipo":"comparar","titulo":"Je t'aime o je t'aime bien: una palabra lo cambia todo","malTitulo":"Evita","mal":"Decirle <i>Je t'aime!</i> a un compañero de trabajo para decir «me caes bien».<br><i>J'aime café.</i> (sin artículo)","bienTitulo":"Correcto","bien":"<i>Je t'aime <b>bien</b>.</i> = me caes bien. <i>Je t'aime</i> solo = te amo.<br><i>J'aime <b>le</b> café.</i> / <i>J'aime <b>les</b> tacos.</i>"},{"tipo":"comparar","titulo":"La negación: el verbo va en medio","malTitulo":"Evita","mal":"<i>Je ne pas parle anglais.</i><br><i>Je ne aime pas le froid.</i><br><i>Je n'ai pas une voiture.</i>","bienTitulo":"Correcto","bien":"<i>Je <b>ne</b> parle <b>pas</b> anglais.</i><br><i>Je <b>n'</b>aime pas le froid.</i> (ne → n' antes de vocal)<br><i>Je n'ai pas <b>de</b> voiture.</i> (tras la negación, <i>un, une, des</i> → <b>de</b>)<br>En la calle oirás <i>J'aime pas</i>, sin <i>ne</i>: es informal."},{"tipo":"dialogo","titulo":"Diálogo — Nueva compañera de departamento en Montreal","lineas":[{"quien":"Chloé","en":"Tu aimes le café?","es":"¿Te gusta el café?"},{"quien":"Valeria","en":"Non, je n'aime pas le café. Je préfère le thé.","es":"No, no me gusta el café. Prefiero el té."},{"quien":"Chloé","en":"Moi, j'adore le café! Et tu aimes cuisiner?","es":"¡A mí me encanta el café! ¿Y te gusta cocinar?"},{"quien":"Valeria","en":"Oui, j'aime beaucoup cuisiner. Le samedi, je prépare des tacos!","es":"Sí, me gusta mucho cocinar. ¡Los sábados preparo tacos!"},{"quien":"Chloé","en":"Super! Moi, je déteste cuisiner, mais j'adore manger!","es":"¡Genial! Yo odio cocinar, ¡pero me encanta comer!"},{"quien":"Valeria","en":"Parfait! Tu manges avec moi samedi?","es":"¡Perfecto! ¿Comes conmigo el sábado?"}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«No hablo alemán»","ops":["Je parle ne pas allemand.","Je ne pas parle allemand.","Je ne parle pas allemand."],"correcta":2},{"p":"«No tengo coche»","ops":["Je n'ai pas une voiture.","Je n'ai pas de voiture.","Je n'ai voiture pas."],"correcta":1,"explica":"Después de <i>ne… pas</i>, <i>une</i> se vuelve <b>de</b>."},{"p":"Quieres decirle a una colega «me caes bien».","ops":["Je t'aime bien.","Je t'aime.","Je t'adore, mon amour."],"correcta":0},{"p":"«Me gustan los tacos»","ops":["J'aime tacos.","J'aime les tacos.","J'aime des tacos."],"correcta":1,"explica":"Con gustos se usa <b>le, la, les</b>."},{"p":"<i>Je préfère</i> se pronuncia aprox.…","ops":["yö prefér","yö preför","yö prefére"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Arma la frase","voz":true,"items":[{"frase":"Je n'aime pas le café","es":"No me gusta el café"},{"frase":"Nous ne travaillons pas le dimanche","es":"No trabajamos los domingos"},{"frase":"Tu aimes cuisiner le week-end?","es":"¿Te gusta cocinar el fin de semana?"},{"frase":"J'adore la musique mexicaine","es":"Me encanta la música mexicana"}]},{"tipo":"pronunciar","rotulo":"Dilo con convicción","frases":[{"en":"J'adore la musique mexicaine.","pron":"yadór la müzík meksikén","es":"Me encanta la música mexicana."},{"en":"Je n'aime pas du tout le froid.","pron":"yö ném pa dü tu lö fruá","es":"No me gusta nada el frío."},{"en":"Je préfère le thé.","pron":"yö prefér lö té","es":"Prefiero el té."},{"en":"Je déteste attendre le bus.","pron":"yö detést atãdr lö büs","es":"Odio esperar el camión."}]},{"tipo":"clave","items":["<i>adorer › aimer beaucoup › aimer bien › ne pas aimer › détester</i>.","Gustos con <b>le, la, les</b> o con infinitivo: <i>J'aime le café, j'aime danser</i>.","<i>ne</i> + verbo + <i>pas</i>; tras la negación, <i>un/une/des</i> → <b>de</b>.","<i>Je t'aime bien</i> = me caes bien. Pasa a la evaluación: necesitas 80%."]}],"c-frances-a1-m4-l1":[{"tipo":"texto","texto":"<b>Il y a</b> (il ia) significa «hay», y sirve igual para una cosa o para muchas: <i>Il y a un musée</i>, <i>Il y a deux musées</i>. En negativo: <b>il n'y a pas de</b>: <i>Il n'y a pas de banque ici</i> (no hay banco aquí). Para preguntar: <i>Est-ce qu'il y a une pharmacie près d'ici?</i> Y para ubicar: <b>près de</b> (cerca de), <b>loin de</b> (lejos de), <b>à côté de</b> (al lado de), <b>en face de</b> (enfrente de), <b>devant</b> (delante de), <b>derrière</b> (detrás de) y <b>entre</b>. Recuerda las contracciones: <i>de + le = <b>du</b></i> y <i>de + les = <b>des</b></i>: <i>à côté du musée</i>."},{"tipo":"tabla","titulo":"Lugares de la ciudad","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["la gare","la estación de tren"],["la station de métro","la estación del metro"],["l'arrêt de bus","la parada del camión"],["la pharmacie","la farmacia"],["la banque","el banco"],["le distributeur","el cajero automático"],["la poste","el correo"],["le supermarché","el súper"],["la boulangerie","la panadería"],["le marché","el mercado"],["le musée","el museo"],["la place","la plaza"]]},{"tipo":"tabla","titulo":"¿Dónde está?","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["La pharmacie est à côté de la banque.","La farmacia está al lado del banco."],["La gare est en face du musée.","La estación está enfrente del museo."],["L'hôtel est près de la place.","El hotel está cerca de la plaza."],["Le marché est loin d'ici.","El mercado está lejos de aquí."],["L'arrêt de bus est devant l'hôtel.","La parada del camión está delante del hotel."],["La banque est entre la poste et le café.","El banco está entre el correo y el café."]],"nota":"Para decir dónde está algo se usa <b>être</b>: <i>La gare <b>est</b> en face du musée</i>. Para decir que algo existe, <b>il y a</b>: <i><b>Il y a</b> une gare</i>."},{"tipo":"comparar","titulo":"Falsos amigos en la ciudad","malTitulo":"Parece que significa","mal":"<i>le magasin</i> = almacén<br><i>le car</i> = carro<br><i>la station</i> = estación de tren<br><i>il a une pharmacie</i> = hay una farmacia","bienTitulo":"En realidad significa","bien":"<i><b>le magasin</b></i> = la tienda (un almacén o bodega es <i>un entrepôt</i>)<br><i><b>le car</b></i> = el autobús foráneo (el carro es <i>la voiture</i>)<br><i><b>la station</b></i> = estación de metro; la de tren es <i><b>la gare</b></i><br><i>il a</i> = él tiene; «hay» es <i><b>il y a</b></i>"},{"tipo":"dialogo","titulo":"Diálogo — Recepción de un hotel en el centro de Oaxaca","lineas":[{"quien":"Hugo","en":"Excusez-moi, est-ce qu'il y a une pharmacie près d'ici?","es":"Disculpe, ¿hay una farmacia cerca de aquí?"},{"quien":"Lupita","en":"Oui, il y a une pharmacie à côté de la banque, en face de la cathédrale.","es":"Sí, hay una farmacia al lado del banco, enfrente de la catedral."},{"quien":"Hugo","en":"Et un distributeur?","es":"¿Y un cajero?"},{"quien":"Lupita","en":"Il y a un distributeur dans la banque.","es":"Hay un cajero en el banco."},{"quien":"Hugo","en":"Super. Et il y a un marché dans le quartier?","es":"Genial. ¿Y hay un mercado en el barrio?"},{"quien":"Lupita","en":"Oui, le marché Benito Juárez. Il est derrière la place, à cinq minutes.","es":"Sí, el mercado Benito Juárez. Está detrás de la plaza, a cinco minutos."},{"quien":"Hugo","en":"Merci beaucoup!","es":"¡Muchas gracias!"},{"quien":"Lupita","en":"Je vous en prie. Bonne journée!","es":"De nada. ¡Que tenga buen día!"}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«Hay dos museos en la ciudad»","ops":["Il y a deux musées dans la ville.","Ils y a deux musées dans la ville.","Il a deux musées dans la ville."],"correcta":0,"explica":"<b>il y a</b> no cambia en plural."},{"p":"«No hay banco aquí»","ops":["Il n'y a pas une banque ici.","Il n'y a pas de banque ici.","Il y a pas banque ici."],"correcta":1},{"p":"La farmacia está al lado del museo: <i>La pharmacie est à côté ___ musée.</i>","ops":["de le","du","de la"],"correcta":1,"explica":"<b>de + le = du</b>."},{"p":"Buscas el tren a Lyon. ¿Adónde vas?","ops":["à la station","au car","à la gare"],"correcta":2},{"p":"<i>Le magasin est fermé.</i> ¿Qué está cerrado?","ops":["La bodega","La tienda","La revista"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa","voz":true,"items":[{"frase":"Il y ___ un musée dans la rue.","resp":["a"],"es":"Hay un museo en la calle."},{"frase":"Il n'y a pas ___ banque ici.","resp":["de"],"es":"No hay banco aquí."},{"frase":"La pharmacie est à côté ___ supermarché.","resp":["du"],"es":"La farmacia está al lado del súper."},{"frase":"Le café est en face ___ la gare.","resp":["de"],"es":"El café está enfrente de la estación."},{"frase":"Est-ce qu'il y a un distributeur près d'___?","resp":["ici"],"es":"¿Hay un cajero cerca de aquí?"}]},{"tipo":"clave","items":["<b>il y a</b> = hay (singular y plural) · <b>il n'y a pas de</b> = no hay.","<i>près de, loin de, à côté de, en face de, devant, derrière, entre</i>.","<i>de + le = du</i>: <i>en face du musée</i>.","<i>la gare</i> = tren · <i>la station</i> = metro · <i>le magasin</i> = tienda."]}],"c-frances-a1-m4-l2":[{"tipo":"texto","texto":"Para preguntar el camino, empieza siempre con <i>Excusez-moi</i> y después: <b>Pour aller à la gare, s'il vous plaît?</b> (¿Para ir a la estación, por favor?), <b>Où est le musée?</b> o <b>Je cherche la rue Victor-Hugo</b>. Las indicaciones se dan con el <b>imperativo de vous</b>, que es el presente sin el pronombre: <i>vous allez → <b>allez</b></i>, <i>vous tournez → <b>tournez</b></i>, <i>vous prenez → <b>prenez</b></i>. Y la trampa número uno: <b>à droite</b> es «a la derecha», pero <b>tout droit</b> es «derecho», todo recto."},{"tipo":"tabla","titulo":"Indicaciones","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español"],"filas":[["Allez tout droit.","alé tu druá","Siga derecho."],["Tournez à droite.","turné a druát","Dé vuelta a la derecha."],["Tournez à gauche.","turné a gosh","Dé vuelta a la izquierda."],["Prenez la première rue à gauche.","pröné la prömiér rü a gosh","Tome la primera calle a la izquierda."],["Prenez la deuxième rue à droite.","pröné la döziém rü a druát","Tome la segunda calle a la derecha."],["Traversez la place.","traversé la plas","Cruce la plaza."],["Continuez jusqu'au feu.","kõtinüé yüskó fö","Siga hasta el semáforo."],["C'est au coin de la rue.","sé to kuẽ dö la rü","Está en la esquina."],["C'est à dix minutes à pied.","sé ta di minüt a pié","Está a diez minutos caminando."]]},{"tipo":"comparar","titulo":"Derecha no es derecho","malTitulo":"Evita","mal":"Pensar que <i>à droite</i> es «derecho».<br>Pensar que <i>tout droit</i> es «a la derecha».","bienTitulo":"Correcto","bien":"<i><b>à droite</b></i> = a la derecha (se oye la t: druát)<br><i><b>tout droit</b></i> = derecho, todo recto (sin t: druá)<br><i><b>à gauche</b></i> = a la izquierda"},{"tipo":"dialogo","titulo":"Diálogo — Buscando el metro en París","lineas":[{"quien":"Sergio","en":"Excusez-moi, madame. Pour aller à la station de métro, s'il vous plaît?","es":"Disculpe, señora. ¿Para ir a la estación del metro, por favor?"},{"quien":"La dame","en":"La station Bastille? Allez tout droit, puis prenez la deuxième rue à gauche.","es":"¿La estación Bastille? Siga derecho y luego tome la segunda calle a la izquierda."},{"quien":"Sergio","en":"Tout droit, puis la deuxième à gauche. C'est loin?","es":"Derecho y luego la segunda a la izquierda. ¿Está lejos?"},{"quien":"La dame","en":"Non, c'est à cinq minutes à pied. La station est en face d'une grande place.","es":"No, está a cinco minutos caminando. La estación está enfrente de una plaza grande."},{"quien":"Sergio","en":"Merci beaucoup, madame!","es":"¡Muchas gracias, señora!"},{"quien":"La dame","en":"De rien. Bonne journée!","es":"De nada. ¡Que tenga buen día!"}]},{"tipo":"practica","rotulo":"¿Hacia dónde vas?","preguntas":[{"p":"Te dicen <i>Allez tout droit.</i> Tú…","ops":["das vuelta a la derecha","sigues derecho","regresas"],"correcta":1},{"p":"Te dicen <i>Tournez à gauche.</i> Tú…","ops":["das vuelta a la izquierda","das vuelta a la derecha","cruzas la calle"],"correcta":0},{"p":"<i>Continuez jusqu'au feu</i> significa…","ops":["Siga hasta el fuego.","Siga hasta el final.","Siga hasta el semáforo."],"correcta":2,"explica":"<b>le feu</b> es el fuego y también el semáforo."},{"p":"«Tome la segunda calle a la derecha»","ops":["Prenez la deuxième rue à droite.","Prenez la second rue tout droit.","Tournez deux rues droit."],"correcta":0},{"p":"¿Cuál es la forma más natural de preguntar el camino?","ops":["Où la gare?","Pour aller à la gare, s'il vous plaît?","Je vais la gare?"],"correcta":1}]},{"tipo":"ordenar","rotulo":"Arma las indicaciones","voz":true,"items":[{"frase":"Allez tout droit jusqu'au feu","es":"Siga derecho hasta el semáforo"},{"frase":"Prenez la deuxième rue à gauche","es":"Tome la segunda calle a la izquierda"},{"frase":"Pour aller à la gare, s'il vous plaît?","es":"¿Para ir a la estación, por favor?"},{"frase":"La banque est au coin de la rue","es":"El banco está en la esquina"}]},{"tipo":"escuchar","rotulo":"Escucha y repite","frases":[{"en":"Tournez à droite, puis allez tout droit.","pron":"turné a druát püí alé tu druá","es":"Dé vuelta a la derecha y luego siga derecho."},{"en":"Traversez la place et continuez.","pron":"traversé la plas e kõtinüé","es":"Cruce la plaza y siga."},{"en":"C'est à côté de la pharmacie.","pron":"sé ta kote dö la farmasí","es":"Está al lado de la farmacia."},{"en":"Vous êtes perdu? Je peux vous aider.","pron":"vu zét perdü? yö pö vu zedé","es":"¿Está perdido? Lo puedo ayudar."}]},{"tipo":"clave","items":["<i>Pour aller à…, s'il vous plaît?</i> · <i>Où est…?</i> · <i>Je cherche…</i>","<i>allez, tournez, prenez, traversez, continuez</i>.","<b>à droite</b> = a la derecha · <b>tout droit</b> = derecho · <b>à gauche</b> = a la izquierda.","<i>le feu</i> = el semáforo · <i>au coin</i> = en la esquina · <i>à pied</i> = caminando."]}],"c-frances-a1-m4-l3":[{"tipo":"texto","texto":"<b>Aller</b> (ir) y <b>venir</b> (venir) son irregulares, pero los vas a usar todo el día. Con <i>aller</i> va <b>à</b> y con <i>venir</i> va <b>de</b>, con sus contracciones: <i>je vais <b>au</b> cinéma</i> (à + le), <i>je vais <b>aux</b> États-Unis</i> (à + les), <i>je viens <b>du</b> bureau</i> (de + le). El transporte: <b>en</b> si vas adentro (<i>en bus, en métro, en voiture, en avion</i>) y <b>à</b> si vas encima o con tus pies (<i>à pied, à vélo, à moto</i>). Y un regalo: el <b>futuro próximo</b> es igual que en español: <i>aller</i> + infinitivo. <i>Je vais manger</i> = voy a comer, pero <b>sin la «a»</b>."},{"tipo":"tabla","titulo":"Aller y venir en presente","voz":true,"colVoz":0,"encabezados":["Aller, venir","Se lee aprox.","Español"],"filas":[["je vais, je viens","yö vé, yö viẽ","voy, vengo"],["tu vas, tu viens","tü va, tü viẽ","vas, vienes"],["il va, il vient","il va, il viẽ","va, viene"],["nous allons, nous venons","nu zalõ, nu vönõ","vamos, venimos"],["vous allez, vous venez","vu zalé, vu vöné","usted va, usted viene"],["ils vont, ils viennent","il võ, il vién","van, vienen"]]},{"tipo":"tabla","titulo":"Adónde, cómo y qué vas a hacer","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["Je vais au travail en bus.","Voy al trabajo en camión."],["Je vais à l'aéroport en taxi.","Voy al aeropuerto en taxi."],["Nous allons au musée à pied.","Vamos al museo caminando."],["Elle vient du Mexique.","Ella viene de México."],["Je viens de Guadalajara.","Vengo de Guadalajara."],["Ce soir, je vais prendre le métro.","Esta noche voy a tomar el metro."],["Demain, nous allons visiter le Louvre.","Mañana vamos a visitar el Louvre."],["Ils vont arriver à dix heures.","Van a llegar a las diez."]],"nota":"Con ciudades: <i>je vais <b>à</b> Paris</i>, <i>je viens <b>de</b> Paris</i>. Con países masculinos: <i>au Mexique, au Canada</i>; femeninos: <i>en France</i>."},{"tipo":"comparar","titulo":"El futuro próximo, sin «a»","malTitulo":"Evita","mal":"<i>Je vais à manger.</i><br><i>Je vais à le cinéma.</i><br><i>Je vais en pied.</i>","bienTitulo":"Correcto","bien":"<i>Je vais <b>manger</b>.</i> (nada entre <i>aller</i> y el infinitivo)<br><i>Je vais <b>au</b> cinéma.</i> (à + le = au)<br><i>Je vais <b>à</b> pied.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Capacitación en Toulouse: planes para el sábado","lineas":[{"quien":"Karen","en":"Qu'est-ce que tu vas faire samedi?","es":"¿Qué vas a hacer el sábado?"},{"quien":"Luis","en":"Je vais visiter Carcassonne! Tu viens avec moi?","es":"¡Voy a visitar Carcassonne! ¿Vienes conmigo?"},{"quien":"Karen","en":"Oui, avec plaisir! On va en voiture?","es":"¡Sí, con gusto! ¿Vamos en coche?"},{"quien":"Luis","en":"Non, on va prendre le train. C'est plus simple.","es":"No, vamos a tomar el tren. Es más fácil."},{"quien":"Karen","en":"Le train part à quelle heure?","es":"¿A qué hora sale el tren?"},{"quien":"Luis","en":"À neuf heures dix. On va arriver vers dix heures.","es":"A las nueve y diez. Vamos a llegar como a las diez."},{"quien":"Karen","en":"Parfait. Je vais réserver les billets ce soir.","es":"Perfecto. Voy a reservar los boletos esta noche."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"Nous ___ au bureau en métro.","ops":["allons","vont","venons"],"correcta":0},{"p":"«Voy a comer»","ops":["Je vais à manger.","Je vais manger.","Je vais mange."],"correcta":1},{"p":"«Vengo de la oficina»","ops":["Je viens de le bureau.","Je viens au bureau.","Je viens du bureau."],"correcta":2,"explica":"<b>de + le = du</b>."},{"p":"«Voy caminando al trabajo»","ops":["Je vais au travail à pied.","Je vais au travail en pied.","Je vais à le travail à pied."],"correcta":0},{"p":"Ils ___ du Canada.","ops":["vient","viennent","venez"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa","voz":true,"items":[{"frase":"Je ___ au bureau en métro. (aller)","resp":["vais"],"es":"Voy a la oficina en metro."},{"frase":"Nous ___ à pied. (aller)","resp":["allons"],"es":"Vamos caminando."},{"frase":"Ils ___ du Canada. (venir)","resp":["viennent"],"es":"Vienen de Canadá."},{"frase":"Demain, je vais ___ le musée. (visitar)","resp":["visiter"],"es":"Mañana voy a visitar el museo."},{"frase":"Tu vas ___ cinéma ce soir?","resp":["au"],"es":"¿Vas al cine esta noche?"}]},{"tipo":"tarjetas","rotulo":"Medios de transporte","voz":true,"vozEn":"reverso","instruccion":"Ves el transporte en español; dilo en francés con <i>en</i> o <i>à</i> antes de voltear.","tarjetas":[{"frente":"en avión","reverso":"en avion","ej":"Je vais à Paris en avion."},{"frente":"caminando","reverso":"à pied","ej":"Je vais à la boulangerie à pied."},{"frente":"en bici","reverso":"à vélo","ej":"Elle va au travail à vélo."},{"frente":"en metro","reverso":"en métro","ej":"On va au Louvre en métro."},{"frente":"en coche","reverso":"en voiture","ej":"Nous allons à Lyon en voiture."},{"frente":"en camión urbano","reverso":"en bus","ej":"Je rentre en bus."}]},{"tipo":"clave","items":["<i>aller</i>: <i>vais, vas, va, allons, allez, vont</i> · <i>venir</i>: <i>viens, viens, vient, venons, venez, viennent</i>.","<i>aller <b>à</b></i> (au, aux) · <i>venir <b>de</b></i> (du, des).","<b>en</b> bus, métro, voiture, avion · <b>à</b> pied, vélo.","Futuro próximo: <i>je vais</i> + infinitivo, sin «à»."]}],"c-frances-a1-m4-l4":[{"tipo":"texto","texto":"En español decimos «compro pan» o «quiero agua», sin artículo. En francés hay que poner algo: el <b>partitivo</b>, que significa «un poco de», «una parte de». Es <b>du</b> (masculino), <b>de la</b> (femenino), <b>de l'</b> (antes de vocal) y <b>des</b> (plural): <i>J'achète <b>du</b> pain et <b>de la</b> confiture</i>. Cuando dices una cantidad, todo eso se simplifica a <b>de</b>: <i>un kilo <b>de</b> tomates, une bouteille <b>d'</b>eau, beaucoup <b>de</b> fruits</i>. Y en negativo también: <i>Il n'y a pas <b>de</b> pain</i>."},{"tipo":"tabla","titulo":"Los partitivos","voz":true,"colVoz":1,"encabezados":["Partitivo","Ejemplo","Español"],"filas":[["du (masculino)","du pain, du fromage","pan, queso"],["de la (femenino)","de la confiture, de la viande","mermelada, carne"],["de l' (antes de vocal)","de l'eau, de l'huile","agua, aceite"],["des (plural)","des fruits, des œufs","fruta, huevos"],["de (cantidad)","un kilo de tomates","un kilo de jitomates"],["de (negación)","pas de sucre","sin azúcar, nada de azúcar"]]},{"tipo":"tabla","titulo":"En la boulangerie y el mercado","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["une baguette","una baguette (el pan largo)"],["un croissant","un cuernito"],["un pain au chocolat","un pan relleno de chocolate"],["une tarte aux pommes","un pay de manzana"],["un gâteau","un pastel"],["un kilo de tomates","un kilo de jitomates"],["deux cents grammes de fromage","200 gramos de queso"],["une bouteille d'eau","una botella de agua"],["une douzaine d'œufs","una docena de huevos"]],"nota":"Frases del vendedor: <i>Et avec ceci?</i> (¿Algo más?), <i>Ce sera tout?</i> (¿Sería todo?), <i>Il n'y a plus de…</i> (Ya no hay…)."},{"tipo":"comparar","titulo":"Falsos amigos en la comida","malTitulo":"Parece que significa","mal":"<i>le raisin</i> = la pasa<br><i>la glace</i> = el hielo<br><i>la limonade</i> = la limonada","bienTitulo":"En realidad significa","bien":"<i><b>le raisin</b></i> = la uva (la pasa es <i>le raisin sec</i>)<br><i><b>la glace</b></i> = el helado (el hielo para la bebida es <i>un glaçon</i>)<br><i><b>la limonade</b></i> = un refresco de limón con gas, tipo Sprite (la limonada es <i>une citronnade</i>)"},{"tipo":"comparar","titulo":"El partitivo no se puede quitar","malTitulo":"Evita","mal":"<i>J'achète pain.</i><br><i>Un kilo des tomates.</i><br><i>Il n'y a pas du pain.</i>","bienTitulo":"Correcto","bien":"<i>J'achète <b>du</b> pain.</i><br><i>Un kilo <b>de</b> tomates.</i> (tras una cantidad, solo <i>de</i>)<br><i>Il n'y a pas <b>de</b> pain.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Una boulangerie de París, a las 8 de la mañana","lineas":[{"quien":"La boulangère","en":"Bonjour, monsieur!","es":"¡Buenos días, señor!"},{"quien":"Daniel","en":"Bonjour, madame! Une baguette et deux croissants, s'il vous plaît.","es":"¡Buenos días, señora! Una baguette y dos cuernitos, por favor."},{"quien":"La boulangère","en":"Et avec ceci?","es":"¿Algo más?"},{"quien":"Daniel","en":"Vous avez des pains au chocolat?","es":"¿Tiene panes de chocolate?"},{"quien":"La boulangère","en":"Non, désolée, il n'y a plus de pains au chocolat. Mais il y a des tartes aux fraises.","es":"No, lo siento, ya no hay panes de chocolate. Pero hay pays de fresa."},{"quien":"Daniel","en":"Alors, je vais prendre une petite tarte aux fraises.","es":"Entonces voy a llevar un pay de fresa chico."},{"quien":"La boulangère","en":"Très bien. Ça fait six euros vingt.","es":"Muy bien. Son seis euros con veinte."}]},{"tipo":"practica","rotulo":"Elige el partitivo","preguntas":[{"p":"J'achète ___ pain.","ops":["de la","du","des"],"correcta":1},{"p":"Je prends ___ eau.","ops":["de l'","du","de la"],"correcta":0,"explica":"Antes de vocal: <b>de l'</b>."},{"p":"Un kilo ___ tomates, s'il vous plaît.","ops":["des","de les","de"],"correcta":2,"explica":"Tras una cantidad, solo <b>de</b>."},{"p":"<i>Il n'y a plus de croissants.</i> significa…","ops":["Hay más cuernitos.","Ya no hay cuernitos.","No hay muchos cuernitos."],"correcta":1},{"p":"Pides <i>une glace</i> en un café. Te traen…","ops":["un helado","un vaso con hielo","un espejo"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa la lista del súper","voz":true,"items":[{"frase":"J'achète ___ fromage.","resp":["du"],"es":"Compro queso."},{"frase":"Je prends ___ confiture.","resp":["de la"],"es":"Llevo mermelada."},{"frase":"Une bouteille ___ eau minérale.","resp":["d'","d"],"es":"Una botella de agua mineral."},{"frase":"Il n'y a pas ___ sucre.","resp":["de"],"es":"No hay azúcar."},{"frase":"Nous mangeons ___ fruits le matin.","resp":["des"],"es":"Comemos fruta en la mañana."}]},{"tipo":"clave","items":["Partitivo obligatorio: <i>du pain, de la confiture, de l'eau, des fruits</i>.","Tras cantidad o negación, solo <b>de</b>: <i>un kilo de tomates, pas de sucre</i>.","<i>Et avec ceci?</i> = ¿algo más? · <i>il n'y a plus de…</i> = ya no hay…","<i>le raisin</i> = uva · <i>la glace</i> = helado · <i>la limonade</i> = refresco de limón."]}],"c-frances-a1-m4-l5":[{"tipo":"texto","texto":"En Francia los precios se escriben con <b>coma decimal</b>: <b>2,50 €</b>. Y se dicen poniendo «euros» en medio: <i>deux <b>euros</b> cinquante</i>, sin decir «con» ni «céntimos». Para preguntar: <b>C'est combien?</b> o <b>Ça coûte combien?</b> para un producto, y <b>Ça fait combien?</b> para el total. Ojo con la <i>liaison</i>, porque <i>euros</i> empieza con vocal: <i>deux euros</i> (dö zöró), <i>vingt euros</i> (vẽ töró), <i>cent euros</i> (sã töró). En Quebec la moneda es el dólar canadiense: <i>vingt dollars</i>."},{"tipo":"tabla","titulo":"Precios en voz alta","voz":true,"colVoz":1,"encabezados":["Precio","Francés","Se lee aprox."],"filas":[["1,20 €","un euro vingt","ẽ nöró vẽ"],["2,50 €","deux euros cinquante","dö zöró sẽkãt"],["15 €","quinze euros","kẽz öró"],["20 €","vingt euros","vẽ töró"],["80 €","quatre-vingts euros","katr vẽ zöró"],["100 €","cent euros","sã töró"],["250 €","deux cent cinquante euros","dö sã sẽkãt öró"],["1 000 €","mille euros","mil öró"]],"nota":"<i>deux cent<b>s</b></i> lleva s cuando va solo (200), pero no cuando le sigue otro número: <i>deux cent cinquante</i>. <i>mille</i> nunca lleva s."},{"tipo":"tabla","titulo":"Frases para pagar","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["C'est combien?","¿Cuánto cuesta?"],["Ça fait combien?","¿Cuánto es (en total)?"],["Ça fait douze euros.","Son doce euros."],["Je peux payer par carte?","¿Puedo pagar con tarjeta?"],["Je paie en espèces.","Pago en efectivo."],["Vous avez de la monnaie?","¿Tiene cambio?"],["Voici votre ticket.","Aquí está su ticket."],["C'est trop cher!","¡Está muy caro!"]]},{"tipo":"comparar","titulo":"Falsos amigos del dinero","malTitulo":"Parece que significa","mal":"<i>la monnaie</i> = solo la moneda<br><i>un billet</i> = solo un billete<br><i>la carte</i> = la carta","bienTitulo":"En realidad significa","bien":"<i><b>la monnaie</b></i> = el cambio, el sencillo: <i>Vous avez de la monnaie?</i><br><i><b>un billet</b></i> = un billete de dinero <b>y también</b> un boleto: <i>un billet de train</i><br><i><b>la carte</b></i> = la tarjeta (<i>carte bancaire</i>), el mapa o el menú; una carta es <i>une lettre</i>"},{"tipo":"dialogo","titulo":"Diálogo — Puesto de fruta en un mercado de París","lineas":[{"quien":"Le vendeur","en":"Bonjour, madame! Qu'est-ce que je vous sers?","es":"¡Buenos días, señora! ¿Qué le doy?"},{"quien":"Gaby","en":"Bonjour! Un kilo de tomates, s'il vous plaît. Et les fraises, c'est combien?","es":"¡Buenos días! Un kilo de jitomates, por favor. ¿Y las fresas, cuánto cuestan?"},{"quien":"Le vendeur","en":"Quatre euros cinquante la barquette.","es":"Cuatro euros con cincuenta la cajita."},{"quien":"Gaby","en":"Une barquette, alors. Ça fait combien?","es":"Una cajita, entonces. ¿Cuánto es?"},{"quien":"Le vendeur","en":"Ça fait sept euros quatre-vingts.","es":"Son siete euros con ochenta."},{"quien":"Gaby","en":"Je peux payer par carte?","es":"¿Puedo pagar con tarjeta?"},{"quien":"Le vendeur","en":"Désolé, ici, c'est en espèces seulement.","es":"Lo siento, aquí es solo en efectivo."},{"quien":"Gaby","en":"Pas de problème. Voici un billet de dix euros.","es":"No hay problema. Aquí tiene un billete de diez euros."},{"quien":"Le vendeur","en":"Et voici votre monnaie: deux euros vingt. Bonne journée!","es":"Y aquí está su cambio: dos euros con veinte. ¡Que tenga buen día!"}]},{"tipo":"practica","rotulo":"¿Cuánto es?","preguntas":[{"p":"<i>Trois euros quatre-vingt-dix</i>","ops":["3,19 €","3,90 €","4,90 €"],"correcta":1},{"p":"La cajera dice <i>Ça fait soixante-quinze euros</i>. Pagas…","ops":["65 €","57 €","75 €"],"correcta":2},{"p":"«¿Puedo pagar con tarjeta?»","ops":["Je peux payer par carte?","Je peux payer avec la lettre?","Je peux payer en carte?"],"correcta":0},{"p":"<i>Vous avez de la monnaie?</i> te preguntan porque quieren…","ops":["saber tu divisa","cambio o sencillo","ver tus monedas de colección"],"correcta":1},{"p":"¿Cómo se escribe 300 € en letras?","ops":["trois cent euros","trois cents euros","trois centaines euros"],"correcta":1,"explica":"200, 300… llevan s si no les sigue otro número."}]},{"tipo":"relacionar","rotulo":"Relaciona cada precio","voz":true,"pares":[["trois euros cinquante","3,50 €"],["quatre-vingts euros","80 €"],["soixante-dix euros","70 €"],["deux cents euros","200 €"],["douze euros vingt","12,20 €"],["mille euros","1 000 €"]]},{"tipo":"clave","items":["<i>C'est combien? · Ça fait combien?</i>","2,50 € = <i>deux euros cinquante</i>; cuidado con la <i>liaison</i>: <i>deux euros, vingt euros</i>.","<i>par carte</i> (con tarjeta) · <i>en espèces</i> (en efectivo).","<i>la monnaie</i> = cambio · <i>un billet</i> = billete o boleto. Pasa a la evaluación: necesitas 80%."]}],"c-frances-a1-m5-l1":[{"tipo":"texto","texto":"La frase más útil de cualquier viaje es <b>je voudrais</b> (yö vudré): «quisiera», «me gustaría». Es la forma amable de pedir. <i>Je veux</i> (quiero) es correcto, pero dicho a un recepcionista o a un mesero suena exigente, casi como una orden. Otras dos fórmulas que te salvan: <b>Est-ce que vous avez…?</b> (¿Tiene…?) y <b>Est-ce que je peux…?</b> (¿Puedo…?). Y un dato de hotel: en Francia la planta baja es <i>le rez-de-chaussée</i>, y <i>le premier étage</i> es el piso de arriba."},{"tipo":"tabla","titulo":"Frases de hotel","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["Je voudrais réserver une chambre.","Quisiera reservar una habitación."],["Pour deux personnes et trois nuits.","Para dos personas y tres noches."],["J'ai une réservation au nom de Reyes.","Tengo una reservación a nombre de Reyes."],["Le petit-déjeuner est compris?","¿Incluye el desayuno?"],["Quel est le code du wifi?","¿Cuál es la contraseña del wifi?"],["Est-ce que je peux laisser mes bagages?","¿Puedo dejar mi equipaje?"],["La climatisation ne marche pas.","El aire acondicionado no funciona."],["Il n'y a pas de serviettes dans la salle de bains.","No hay toallas en el baño."]]},{"tipo":"comparar","titulo":"Je veux suena a orden","malTitulo":"Evita","mal":"<i>Je veux une chambre.</i><br><i>Donnez-moi la clé.</i>","bienTitulo":"Correcto","bien":"<i><b>Je voudrais</b> une chambre, s'il vous plaît.</i><br><i><b>Est-ce que je peux avoir</b> la clé, s'il vous plaît?</i>"},{"tipo":"comparar","titulo":"Falsos amigos de viaje","malTitulo":"Parece que significa","mal":"<i>L'hôtel est complet</i> = el hotel está completo, muy equipado<br><i>une serviette</i> = una servilleta (solo)<br><i>Je suis constipé</i> = estoy resfriado","bienTitulo":"En realidad significa","bien":"<i><b>complet</b></i> = lleno, ya no hay cuartos<br><i><b>une serviette</b></i> = una toalla, y también una servilleta de mesa<br><i><b>constipé</b></i> = ¡estreñido! Resfriado se dice <i><b>enrhumé</b></i>: <i>Je suis enrhumé.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Check-in en un hotel de París","lineas":[{"quien":"Le réceptionniste","en":"Bonsoir, madame. Bienvenue!","es":"Buenas noches, señora. ¡Bienvenida!"},{"quien":"Mónica","en":"Bonsoir! J'ai une réservation au nom de Reyes.","es":"¡Buenas noches! Tengo una reservación a nombre de Reyes."},{"quien":"Le réceptionniste","en":"Oui, madame Reyes: une chambre double pour trois nuits. Votre passeport, s'il vous plaît.","es":"Sí, señora Reyes: una habitación doble por tres noches. Su pasaporte, por favor."},{"quien":"Mónica","en":"Voici. Est-ce que le petit-déjeuner est compris?","es":"Aquí tiene. ¿Incluye el desayuno?"},{"quien":"Le réceptionniste","en":"Oui, il est servi de sept heures à dix heures, au rez-de-chaussée.","es":"Sí, se sirve de siete a diez, en la planta baja."},{"quien":"Mónica","en":"Parfait. Et je voudrais le code du wifi, s'il vous plaît.","es":"Perfecto. Y quisiera la contraseña del wifi, por favor."},{"quien":"Le réceptionniste","en":"Le code est sur cette carte. Voici votre clé: chambre 312, au troisième étage. Bonne soirée!","es":"La contraseña está en esta tarjeta. Aquí está su llave: habitación 312, en el tercer piso. ¡Buena noche!"}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"Quieres una habitación. Lo más amable es…","ops":["Je veux une chambre.","Je voudrais une chambre, s'il vous plaît.","Une chambre, vite."],"correcta":1},{"p":"«¿Incluye el desayuno?»","ops":["Le petit-déjeuner est compris?","Le déjeuner est complet?","Le petit-déjeuner est constipé?"],"correcta":0},{"p":"Te dicen <i>Désolé, nous sommes complets.</i> Significa que…","ops":["el servicio es completo","ya no hay habitaciones","el desayuno ya pasó"],"correcta":1},{"p":"Tienes gripa y vas a la farmacia. Dices…","ops":["Je suis constipé.","Je suis complet.","Je suis enrhumé."],"correcta":2,"explica":"<b>enrhumé</b> = resfriado. <i>Constipé</i> es estreñido."},{"p":"«El aire acondicionado no funciona»","ops":["La climatisation ne marche pas.","La climatisation ne pas marche.","La climatisation marche ne pas."],"correcta":0}]},{"tipo":"pronunciar","rotulo":"Dilo en la recepción","frases":[{"en":"Je voudrais réserver une chambre, s'il vous plaît.","pron":"yö vudré rezervé ün shãbr sil vu plé","es":"Quisiera reservar una habitación, por favor."},{"en":"J'ai une réservation au nom de Reyes.","pron":"yé ün rezervasiõ o nõ dö reyés","es":"Tengo una reservación a nombre de Reyes."},{"en":"Le petit-déjeuner est compris?","pron":"lö pti deyöné é kõprí","es":"¿Incluye el desayuno?"},{"en":"La climatisation ne marche pas.","pron":"la klimatizasiõ nö marsh pa","es":"El aire acondicionado no funciona."}]},{"tipo":"clave","items":["<b>Je voudrais…</b> para pedir con cortesía; <i>je veux</i> suena a orden.","<i>Est-ce que vous avez…? · Est-ce que je peux…?</i>","<i>complet</i> = lleno · <i>serviette</i> = toalla · <i>enrhumé</i> = resfriado (¡no <i>constipé</i>!).","<i>le rez-de-chaussée</i> = planta baja."]}],"c-frances-a1-m5-l2":[{"tipo":"texto","texto":"En un restaurante francés hay dos opciones: <b>la carte</b> (la carta completa, pides lo que quieras) y <b>le menu</b> o <b>la formule</b>: un paquete a precio fijo, como nuestra comida corrida, con <b>entrée</b> (entrada), <b>plat</b> (plato fuerte) y <b>dessert</b> (postre). Para pedir: <i>Je voudrais…</i>, <i>Pour moi, …</i> o <i>Je vais prendre…</i> El agua de la llave es gratis si pides <b>une carafe d'eau</b>. El servicio ya está incluido en el precio (<i>service compris</i>): dejar propina no es obligatorio. Y para llamar al mesero: <i>Excusez-moi!</i> o <i>Monsieur! / Madame!</i>"},{"tipo":"tabla","titulo":"Frases del restaurante","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español"],"filas":[["Une table pour deux, s'il vous plaît.","ün tabl pur dö sil vu plé","Una mesa para dos, por favor."],["Qu'est-ce que vous recommandez?","kés kö vu rökomãdé","¿Qué nos recomienda?"],["Je voudrais le menu à vingt-cinq euros.","yö vudré lö mönü a vẽt sẽk öró","Quisiera el menú de 25 euros."],["En entrée, la soupe à l'oignon.","ã nãtré la sup a loñõ","De entrada, la sopa de cebolla."],["Comme plat, le poulet rôti.","kom pla lö pulé rotí","De plato fuerte, el pollo rostizado."],["Pour moi, un steak-frites, bien cuit.","pur muá ẽ stek frit biẽ küí","Para mí, un bistec con papas, bien cocido."],["Une carafe d'eau, s'il vous plaît.","ün karáf dó sil vu plé","Una jarra de agua, por favor."],["L'addition, s'il vous plaît.","ladisiõ sil vu plé","La cuenta, por favor."]],"nota":"La carne: <i>saignant</i> (término rojo), <i>à point</i> (término medio), <i>bien cuit</i> (bien cocido). Ojo: en Francia la sirven menos cocida que en México; si la quieres como aquí, pide <i>bien cuit</i>."},{"tipo":"comparar","titulo":"Falsos amigos del restaurante","malTitulo":"Parece que significa","mal":"<i>le menu</i> = la carta completa<br><i>un plat</i> = un plato de la vajilla<br><i>Garçon!</i> = la forma de llamar al mesero<br><i>le compte</i> = la cuenta del restaurante","bienTitulo":"En realidad significa","bien":"<i><b>le menu</b></i> = paquete a precio fijo; la carta completa es <i><b>la carte</b></i><br><i><b>un plat</b></i> = un platillo; el plato donde comes es <i>une assiette</i><br><i>Excusez-moi!</i> (<i>Garçon!</i> suena anticuado y grosero)<br><i><b>L'addition</b>, s'il vous plaît.</i> (<i>le compte</i> es una cuenta de banco)"},{"tipo":"dialogo","titulo":"Diálogo — Una noche en un bistró de París","lineas":[{"quien":"Le serveur","en":"Bonsoir! Vous avez choisi?","es":"¡Buenas noches! ¿Ya eligieron?"},{"quien":"Alejandra","en":"Oui. Nous voudrions deux menus, s'il vous plaît.","es":"Sí. Quisiéramos dos menús del día, por favor."},{"quien":"Le serveur","en":"Très bien. Et en entrée?","es":"Muy bien. ¿Y de entrada?"},{"quien":"Alejandra","en":"Pour moi, la soupe à l'oignon. Et comme plat, le poulet rôti.","es":"Para mí, la sopa de cebolla. Y de plato fuerte, el pollo rostizado."},{"quien":"Óscar","en":"Moi, je vais prendre la salade, puis le steak-frites, bien cuit. Et une carafe d'eau, s'il vous plaît.","es":"Yo voy a pedir la ensalada y luego el bistec con papas, bien cocido. Y una jarra de agua, por favor."},{"quien":"Le serveur","en":"Parfait. Et comme dessert?","es":"Perfecto. ¿Y de postre?"},{"quien":"Alejandra","en":"Deux crèmes brûlées!","es":"¡Dos crèmes brûlées!"},{"quien":"Óscar","en":"Et après, l'addition, s'il vous plaît.","es":"Y después, la cuenta, por favor."}]},{"tipo":"practica","rotulo":"¿Qué dices en el restaurante?","preguntas":[{"p":"Quieres la cuenta.","ops":["Le compte, s'il vous plaît.","L'addition, s'il vous plaît.","La note, garçon!"],"correcta":1},{"p":"Quieres agua de la llave, gratis.","ops":["Une bouteille d'eau minérale.","Une carafe d'eau, s'il vous plaît.","Un verre de limonade."],"correcta":1},{"p":"En la pizarra dice <i>Formule du midi : entrée + plat, 16 €</i>. Es…","ops":["un paquete con entrada y plato fuerte","una fórmula para el postre","la carta completa"],"correcta":0},{"p":"Quieres la carne bien cocida.","ops":["saignant","à point","bien cuit"],"correcta":2},{"p":"«De entrada, una ensalada»","ops":["En entrée, une salade.","Pour entrer, une salade.","À l'entrée, une salade."],"correcta":0}]},{"tipo":"relacionar","rotulo":"El vocabulario de la mesa","voz":true,"pares":[["l'entrée","la entrada"],["le plat","el plato fuerte"],["le dessert","el postre"],["l'addition","la cuenta"],["une assiette","un plato (de la vajilla)"],["la boisson","la bebida"]]},{"tipo":"ordenar","rotulo":"Arma tu pedido","voz":true,"items":[{"frase":"Une table pour deux, s'il vous plaît","es":"Una mesa para dos, por favor"},{"frase":"Je voudrais la soupe à l'oignon","es":"Quisiera la sopa de cebolla"},{"frase":"Pour moi, le poulet rôti","es":"Para mí, el pollo rostizado"},{"frase":"L'addition, s'il vous plaît","es":"La cuenta, por favor"}]},{"tipo":"clave","items":["<i>la carte</i> = carta completa · <i>le menu / la formule</i> = paquete a precio fijo.","<i>entrée</i> (entrada), <i>plat</i> (plato fuerte), <i>dessert</i> (postre).","<i>Je voudrais… · Pour moi… · Je vais prendre…</i>","<i>Une carafe d'eau</i> (gratis) · <i>L'addition, s'il vous plaît.</i>"]}],"c-frances-a1-m5-l3":[{"tipo":"texto","texto":"Para contar lo que ya pasó, el francés de todos los días usa el <b>passé composé</b>: <b>avoir</b> en presente + <b>participio</b>. En los verbos en <i>-er</i> el participio termina en <b>-é</b>: <i>visiter → visité, manger → mangé</i>. Y suena igual que el infinitivo, así que ¡ya lo sabes pronunciar! Sirve para «visité» y para «he visitado». Unos cuantos verbos muy usados son irregulares y hay que memorizarlos. Nota: algunos verbos de movimiento, como <i>aller</i>, usan <i>être</i> (<i>je suis allé</i> = fui); los verás en el siguiente nivel. Por ahora apréndelo como frase hecha."},{"tipo":"tabla","titulo":"Visiter en passé composé","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español"],"filas":[["j'ai visité","yé vizité","visité"],["tu as visité","tü a vizité","visitaste"],["il / elle a visité","il a vizité","visitó"],["nous avons visité","nu zavõ vizité","visitamos"],["vous avez visité","vu zavé vizité","usted visitó · ustedes visitaron"],["ils / elles ont visité","il zõ vizité","visitaron"]]},{"tipo":"tabla","titulo":"Participios que vas a usar mucho","voz":true,"colVoz":1,"encabezados":["Infinitivo","Passé composé","Español"],"filas":[["manger","j'ai mangé","comí"],["acheter","j'ai acheté","compré"],["parler","j'ai parlé","hablé"],["faire","j'ai fait","hice"],["prendre","j'ai pris","tomé"],["voir","j'ai vu","vi"],["boire","j'ai bu","bebí, tomé (una bebida)"],["dormir","j'ai dormi","dormí"]],"nota":"Para ubicar en el tiempo: <i>hier</i> (ayer), <i>hier soir</i> (anoche), <i>le week-end dernier</i> (el fin de semana pasado), <i>la semaine dernière</i> (la semana pasada), <i>il y a deux jours</i> (hace dos días)."},{"tipo":"comparar","titulo":"No olvides avoir","malTitulo":"Evita","mal":"<i>Je visité le Louvre.</i><br><i>Hier, je mange des crêpes.</i><br><i>Je n'ai visité pas le musée.</i>","bienTitulo":"Correcto","bien":"<i>J'<b>ai</b> visité le Louvre.</i><br><i>Hier, j'<b>ai mangé</b> des crêpes.</i><br><i>Je <b>n'ai pas</b> visité le musée.</i> (<i>ne… pas</i> rodea a <i>avoir</i>)"},{"tipo":"escuchar","rotulo":"Escucha lo que hicieron","frases":[{"en":"Hier, j'ai visité la tour Eiffel.","pron":"iér yé vizité la tur efél","es":"Ayer visité la torre Eiffel."},{"en":"Nous avons mangé dans un bistrot.","pron":"nu zavõ mãyé dã zẽ bistró","es":"Comimos en un bistró."},{"en":"J'ai pris beaucoup de photos.","pron":"yé prí bocú dö fotó","es":"Tomé muchas fotos."},{"en":"Tu as vu le Mont-Royal?","pron":"tü a vü lö mõ ruayál","es":"¿Viste el Mont-Royal?"},{"en":"Je n'ai pas bien dormi.","pron":"yö né pa biẽ dormí","es":"No dormí bien."}]},{"tipo":"practica","rotulo":"Elige la forma correcta","preguntas":[{"p":"«Ayer compré un regalo»","ops":["Hier, j'ai acheté un cadeau.","Hier, je acheté un cadeau.","Hier, j'achète un cadeau."],"correcta":0},{"p":"Passé composé de <i>prendre</i>:","ops":["j'ai prendu","j'ai prené","j'ai pris"],"correcta":2},{"p":"Nous ___ un film hier soir.","ops":["avons vu","avez vu","ont vu"],"correcta":0},{"p":"«No comí»","ops":["Je n'ai mangé pas.","Je n'ai pas mangé.","Je ne pas ai mangé."],"correcta":1},{"p":"<i>il y a deux jours</i> significa…","ops":["hay dos días","hace dos días","dentro de dos días"],"correcta":1,"explica":"Con un tiempo, <b>il y a</b> significa «hace»."}]},{"tipo":"completar","rotulo":"Cuenta tu fin de semana","voz":true,"items":[{"frase":"Samedi, j'___ visité le musée.","resp":["ai"],"es":"El sábado visité el museo."},{"frase":"Nous avons ___ des crêpes. (manger)","resp":["mangé","mange"],"es":"Comimos crepas."},{"frase":"Elle a ___ le métro. (prendre)","resp":["pris"],"es":"Ella tomó el metro."},{"frase":"Ils ont ___ un café. (boire)","resp":["bu"],"es":"Tomaron un café."},{"frase":"Qu'est-ce que tu as ___ hier? (faire)","resp":["fait"],"es":"¿Qué hiciste ayer?"}]},{"tipo":"clave","items":["<b>passé composé</b> = <i>avoir</i> + participio: <i>j'ai visité</i>.","<i>-er → -é</i>: <i>mangé, acheté, parlé</i>.","Irregulares: <i>fait, pris, vu, bu, dormi</i>.","Negación: <i>je <b>n'</b>ai <b>pas</b> mangé</i> · <i>il y a</i> + tiempo = hace."]}],"c-frances-a1-m5-l4":[{"tipo":"texto","texto":"Los posesivos concuerdan con <b>la cosa o la persona que se posee</b>, no con el dueño: <b>mon</b> (masculino), <b>ma</b> (femenino), <b>mes</b> (plural). Lo mismo con <i>ton, ta, tes</i> (tu) y <i>son, sa, ses</i> (su). Así, <i>sa mère</i> es «su mamá», sea de él o de ella. Antes de vocal se usa <i>mon</i> aunque sea femenino: <i><b>mon</b> amie</i>. Para invitar: <b>Tu veux venir…?</b> (¿Quieres venir…?) o <b>Ça te dit de…?</b> (¿Se te antoja…?). Para aceptar: <b>Avec plaisir!</b> o <b>Volontiers!</b> Y para decir que no, siempre con una razón: <i>Désolé, je ne peux pas, je travaille.</i>"},{"tipo":"tabla","titulo":"La familia","voz":true,"colVoz":0,"encabezados":["Francés","Se lee aprox.","Español"],"filas":[["mon père","mõ per","mi papá"],["ma mère","ma mer","mi mamá"],["mes parents","me parã","mis papás"],["mon frère","mõ frer","mi hermano"],["ma sœur","ma sör","mi hermana"],["mon mari","mõ marí","mi esposo"],["ma femme","ma fam","mi esposa"],["mon fils","mõ fis","mi hijo"],["ma fille","ma fíi","mi hija"],["mes grands-parents","me grã parã","mis abuelos"]],"nota":"En <i>fils</i> (hijo) la s final sí suena y la l no: «fis». En <i>fille</i> (hija) la ll suena como «i»: «fíi»."},{"tipo":"tabla","titulo":"Invitar, aceptar y rechazar","voz":true,"colVoz":0,"encabezados":["Francés","Español"],"filas":[["Tu veux venir dîner samedi?","¿Quieres venir a cenar el sábado?"],["Ça te dit d'aller au cinéma?","¿Se te antoja ir al cine?"],["On va boire un café?","¿Vamos por un café?"],["Avec plaisir!","¡Con gusto!"],["Oui, volontiers!","¡Sí, claro que sí!"],["D'accord! À quelle heure?","¡Va! ¿A qué hora?"],["Désolé, je ne peux pas. Je travaille.","Lo siento, no puedo. Trabajo."],["Une autre fois, peut-être?","¿Otro día, tal vez?"]]},{"tipo":"comparar","titulo":"Falsos amigos de la familia","malTitulo":"Parece que significa","mal":"<i>mes parents</i> = mis parientes<br><i>ma femme</i> = una mujer cualquiera<br><i>sa mère</i> = solo «la mamá de ella»","bienTitulo":"En realidad significa","bien":"<i><b>mes parents</b></i> = mis papás (para toda la familia di <i>ma famille</i>)<br><i><b>ma femme</b></i> = mi esposa; <i><b>ma fille</b></i> = mi hija<br><i><b>sa mère</b></i> = su mamá, de él o de ella: <i>sa</i> concuerda con <i>mère</i>"},{"tipo":"dialogo","titulo":"Diálogo — Una invitación en Guadalajara","lineas":[{"quien":"Julien","en":"Mariana, tu veux venir dîner chez moi samedi? Ma femme va préparer une raclette.","es":"Mariana, ¿quieres venir a cenar a mi casa el sábado? Mi esposa va a preparar una raclette."},{"quien":"Mariana","en":"Avec plaisir! C'est gentil. Je peux venir avec mon frère? Il est à Guadalajara ce week-end.","es":"¡Con gusto! Qué amable. ¿Puedo ir con mi hermano? Está en Guadalajara este fin de semana."},{"quien":"Julien","en":"Bien sûr! Nos enfants vont être contents.","es":"¡Claro! Nuestros hijos van a estar contentos."},{"quien":"Mariana","en":"Super! À quelle heure?","es":"¡Súper! ¿A qué hora?"},{"quien":"Julien","en":"Vers vingt heures. Ça te va?","es":"Como a las ocho. ¿Te queda bien?"},{"quien":"Mariana","en":"Parfait. J'apporte le dessert!","es":"Perfecto. ¡Yo llevo el postre!"}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«Mi hermana»","ops":["mon sœur","ma sœur","mes sœur"],"correcta":1},{"p":"«Mi amiga» (amie empieza con vocal)","ops":["ma amie","mon amie","m'amie"],"correcta":1,"explica":"Antes de vocal: <b>mon</b>, aunque sea femenino."},{"p":"Pedro habla de la mamá de Pedro: <i>C'est ___ mère.</i>","ops":["son","sa","ses"],"correcta":1,"explica":"<i>mère</i> es femenino → <b>sa</b>, aunque Pedro sea hombre."},{"p":"Te invitan al cine y quieres ir. Dices…","ops":["Désolé, je ne peux pas.","De rien!","Oui, volontiers!"],"correcta":2},{"p":"<i>Mes parents habitent à Puebla.</i> ¿Quiénes viven en Puebla?","ops":["Mis papás","Mis parientes lejanos","Mis padrinos"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa con el posesivo","voz":true,"items":[{"frase":"Je te présente ___ mari, Paul.","resp":["mon"],"es":"Te presento a mi esposo, Paul."},{"frase":"___ enfants ont dix et douze ans.","resp":["Mes"],"es":"Mis hijos tienen diez y doce años."},{"frase":"C'est ___ fille, Lucie.","resp":["ma"],"es":"Es mi hija, Lucie."},{"frase":"Tu veux venir avec ___ sœur?","resp":["ta"],"es":"¿Quieres venir con tu hermana?"},{"frase":"Ça te dit ___ aller au restaurant?","resp":["d'","d"],"es":"¿Se te antoja ir al restaurante?"}]},{"tipo":"clave","items":["<i>mon / ma / mes</i> concuerdan con lo que se posee: <i>sa mère</i> = su mamá (de él o de ella).","Antes de vocal, <i>mon</i>: <i>mon amie</i>.","<i>mes parents</i> = mis papás · <i>ma femme</i> = mi esposa.","Invitar: <i>Tu veux…? Ça te dit de…?</i> · Aceptar: <i>Avec plaisir! Volontiers!</i>"]}],"c-frances-a1-m5-l5":[{"tipo":"texto","texto":"Laura es de Puebla y viaja sola a Montreal, la ciudad francófona más grande de América. Vas a acompañarla y a usar todo lo que aprendiste: saludos, <i>vous</i>, números, <i>il y a</i>, transporte, <i>je voudrais</i>, futuro próximo y <i>passé composé</i>. Algunas diferencias de Quebec que te conviene conocer: se tutea más rápido; se paga en <b>dólares canadienses</b>; comen <i>déjeuner, dîner</i> y <i>souper</i>; y cuando das las gracias, a veces te contestan <b>Bienvenue!</b>, que ahí significa «de nada»."},{"tipo":"dialogo","titulo":"Diálogo — Del aeropuerto al hotel","lineas":[{"quien":"Le chauffeur","en":"Bonjour! Vous allez où?","es":"¡Buenos días! ¿Adónde va?"},{"quien":"Laura","en":"Bonjour! À l'hôtel Le Plateau, rue Saint-Denis, s'il vous plaît.","es":"¡Buenos días! Al hotel Le Plateau, en la calle Saint-Denis, por favor."},{"quien":"Le chauffeur","en":"Vous venez d'où?","es":"¿De dónde viene?"},{"quien":"Laura","en":"Je viens du Mexique, de Puebla. C'est mon premier voyage à Montréal!","es":"Vengo de México, de Puebla. ¡Es mi primer viaje a Montreal!"},{"quien":"Le chauffeur","en":"Bienvenue! Qu'est-ce que vous allez faire?","es":"¡Bienvenida! ¿Qué va a hacer?"},{"quien":"Laura","en":"Demain, je vais visiter le Vieux-Montréal et le marché Jean-Talon.","es":"Mañana voy a visitar el Viejo Montreal y el mercado Jean-Talon."},{"quien":"Le chauffeur","en":"Bonne idée! Voilà l'hôtel. Ça fait quarante dollars.","es":"¡Buena idea! Aquí está el hotel. Son cuarenta dólares."},{"quien":"Laura","en":"Je peux payer par carte?","es":"¿Puedo pagar con tarjeta?"},{"quien":"Le chauffeur","en":"Bien sûr. Bon séjour!","es":"Claro. ¡Buena estancia!"}]},{"tipo":"escuchar","rotulo":"La postal de Laura","frases":[{"en":"Chère Sofía, je suis à Montréal depuis trois jours.","pron":"shér sofía yö süí a mõreál döpüí truá yur","es":"Querida Sofía: estoy en Montreal desde hace tres días."},{"en":"Hier, j'ai visité le Vieux-Montréal et j'ai pris beaucoup de photos.","es":"Ayer visité el Viejo Montreal y tomé muchas fotos."},{"en":"À midi, j'ai mangé une poutine. C'est délicieux!","pron":"a midí yé mãyé ün putín. sé delisiö","es":"A mediodía comí una poutine. ¡Está deliciosa!"},{"en":"Le soir, j'ai rencontré la famille de mon amie Julie.","pron":"lö suár yé rãkõtré la famíi dö mõ namí yülí","es":"En la noche conocí a la familia de mi amiga Julie."},{"en":"Demain, je vais prendre le train pour Québec. Bisous!","es":"Mañana voy a tomar el tren a Quebec. ¡Besos!"}]},{"tipo":"practica","rotulo":"Repaso: ¿qué dice Laura?","preguntas":[{"p":"Laura llega a la recepción a las 9 de la noche. Saluda con…","ops":["Bonne nuit!","Bonsoir!","Salut!"],"correcta":1},{"p":"Quiere saber si hay un cajero cerca.","ops":["Est-ce qu'il y a un distributeur près d'ici?","Il a un distributeur ici?","Où est le distributeur de la carte?"],"correcta":0},{"p":"En el mercado Jean-Talon pide medio kilo de fresas con cortesía.","ops":["Je veux des fraises.","Je voudrais une livre de fraises, s'il vous plaît.","Donnez fraises."],"correcta":1,"explica":"<i>une livre</i> = una libra, casi medio kilo; se usa mucho en los mercados."},{"p":"Le cuenta a su amiga que ayer tomó el metro.","ops":["Hier, je vais prendre le métro.","Hier, j'ai pris le métro.","Hier, je prends le métro."],"correcta":1},{"p":"Julie le dice <i>Merci!</i> y Laura contesta a la quebequense…","ops":["Bienvenue!","Au revoir!","Enchantée!"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa el viaje de Laura","voz":true,"items":[{"frase":"Je ___ mexicaine, de Puebla.","resp":["suis"],"es":"Soy mexicana, de Puebla."},{"frase":"J'___ vingt-huit ans.","resp":["ai"],"es":"Tengo veintiocho años."},{"frase":"Demain, je vais ___ le musée. (visitar)","resp":["visiter"],"es":"Mañana voy a visitar el museo."},{"frase":"Hier, j'ai ___ une poutine. (comer)","resp":["mangé","mange"],"es":"Ayer comí una poutine."},{"frase":"Je ___ une chambre pour deux nuits, s'il vous plaît.","resp":["voudrais"],"es":"Quisiera una habitación para dos noches, por favor."},{"frase":"L'___, s'il vous plaît.","resp":["addition"],"es":"La cuenta, por favor."}]},{"tipo":"ordenar","rotulo":"Arma las frases del viaje","voz":true,"items":[{"frase":"Je viens du Mexique, de Puebla","es":"Vengo de México, de Puebla"},{"frase":"Demain je vais prendre le train","es":"Mañana voy a tomar el tren"},{"frase":"Hier j'ai visité le Vieux-Montréal","es":"Ayer visité el Viejo Montreal"},{"frase":"Je voudrais une carafe d'eau, s'il vous plaît","es":"Quisiera una jarra de agua, por favor"}]},{"tipo":"reflexion","rotulo":"Tu postal","pregunta":"Imagina que estás de viaje en París o en Montreal. Escribe una postal de 5 frases a un amigo: dónde estás, qué hiciste ayer (dos cosas), qué comiste y qué vas a hacer mañana. Después léela en voz alta.","ayuda":"Cher… / Chère…, je suis à… Hier, j'ai visité… et j'ai pris… À midi, j'ai mangé… Demain, je vais… Bisous!"},{"tipo":"clave","items":["Saludar, presentarte y pedir con <i>je voudrais</i> te abre todas las puertas.","Presente para hoy, <i>je vais</i> + infinitivo para mañana, <i>j'ai</i> + participio para ayer.","En Quebec: dólares, <i>souper</i> para la cena y <i>Bienvenue!</i> = de nada.","Pasa a la evaluación final del módulo: necesitas 80%. ¡Félicitations!"]}]},"q":{"c-frances-a1-m1":[{"p":"Llegas a un restaurante a las 8 de la noche. Saludas con…","ops":["Bonne nuit!","Bonsoir!","Bonne soirée!","Salut, monsieur!"],"correcta":1},{"p":"Hablas con una clienta en tu hotel. ¿Qué pregunta es la adecuada?","ops":["Ça va, toi?","Comment vas-tu?","Comment allez-vous?","Comment tu es?"],"correcta":2},{"p":"«Estoy bien, gracias» se dice…","ops":["Je suis bien, merci.","Je vais bien, merci.","Suis bien, merci.","Je va bien, merci."],"correcta":1},{"p":"«Vivo en Guadalajara» se dice…","ops":["J'habite à Guadalajara.","J'habite en Guadalajara.","Je habite à Guadalajara.","J'habite au Guadalajara."],"correcta":0},{"p":"Completa: <i>Nous ___ de Puebla.</i>","ops":["sont","êtes","sommes","est"],"correcta":2},{"p":"Te presentan a Julien. ¿Cómo dices «Es mi compañero»?","ops":["Il est mon collègue.","C'est mon collègue.","Est mon collègue.","Il c'est mon collègue."],"correcta":1},{"p":"¿En qué palabra suena la «u» francesa (ü)?","ops":["vous","bonjour","salut"],"correcta":2},{"p":"¿En cuál de estas frases hay <i>liaison</i> (una s que suena como z)?","ops":["ils sont","les amis","les parcs","le vin"],"correcta":1}],"c-frances-a1-m2":[{"p":"¿Qué número es <i>quatre-vingt-dix</i>?","ops":["49","80","90","94"],"correcta":2},{"p":"¿Cómo se dice 71?","ops":["soixante-onze","soixante et onze","septante et un","soixante-dix-un"],"correcta":1},{"p":"«Tengo 40 años» se dice…","ops":["Je suis quarante ans.","J'ai quarante.","J'ai quarante ans.","J'ai quarante années."],"correcta":2},{"p":"Completa: <i>Mes amis ___ une maison à Oaxaca.</i>","ops":["sont","ont","avons","a"],"correcta":1},{"p":"Tu hermana es enfermera. Dices: <i>Elle est…</i>","ops":["une infirmière","infirmier","infirmière","un infirmier"],"correcta":2},{"p":"«La leche» en francés es…","ops":["la lait","le lait","les laits","l'lait"],"correcta":1},{"p":"Completa: <i>___ est votre adresse?</i>","ops":["Quel","Quoi","Quelle","Qu'est-ce que"],"correcta":2},{"p":"¿Cuál es una pregunta correcta?","ops":["Où vous habitez est-ce que?","Où est-ce que vous habitez?","Où habitez vous est?","Est-ce que où vous habitez?"],"correcta":1}],"c-frances-a1-m3":[{"p":"Completa: <i>Nous ___ français au bureau.</i>","ops":["parlent","parlons","parlez","parle"],"correcta":1},{"p":"¿Cómo suena el final de <i>ils mangent</i>?","ops":["No suena: «il mãy»","«mãyã», con nasal","«mãyént»","«mãyé»"],"correcta":0},{"p":"«Son las cuatro y media»","ops":["Sont quatre heures et demie.","Il est quatre et demie.","Il est quatre heures et demie.","Il est quatre heures moins demie."],"correcta":2},{"p":"<i>Il est neuf heures moins le quart.</i> ¿Qué hora es?","ops":["9:15","9:45","8:45","8:15"],"correcta":2},{"p":"En Francia, <i>le déjeuner</i> es…","ops":["el desayuno","la comida del mediodía","la cena","un refrigerio de media tarde"],"correcta":1},{"p":"«El 5 de mayo»","ops":["le cinq de mai","la cinq mai","le cinquième de mai","le cinq mai"],"correcta":3},{"p":"<i>Je reste à la maison</i> significa…","ops":["Me quedo en casa.","Descanso en casa.","Regreso a casa.","Arreglo la casa."],"correcta":0},{"p":"«No tengo hijos»","ops":["Je n'ai pas des enfants.","Je n'ai pas d'enfants.","Je ne pas ai enfants.","Je n'ai enfants pas."],"correcta":1}],"c-frances-a1-m4":[{"p":"«Hay una farmacia al lado del banco»","ops":["Il a une pharmacie à côté de la banque.","Il y a une pharmacie à côté de la banque.","Il est une pharmacie à côté de la banque.","Ils y a une pharmacie à côté de la banque."],"correcta":1},{"p":"Te dicen <i>Allez tout droit.</i> ¿Qué haces?","ops":["Sigues derecho.","Das vuelta a la derecha.","Das vuelta a la izquierda.","Te regresas."],"correcta":0},{"p":"Quieres tomar el tren a Burdeos. Vas a…","ops":["la station","le car","le magasin","la gare"],"correcta":3},{"p":"«Mañana voy a visitar el museo»","ops":["Demain, je vais à visiter le musée.","Demain, je visite à le musée.","Demain, je vais visiter le musée.","Demain, je viens visiter le musée."],"correcta":2},{"p":"Completa: <i>Ils ___ du Canada.</i>","ops":["viennent","vient","venons","vont"],"correcta":0},{"p":"Completa: <i>J'achète un kilo ___ tomates.</i>","ops":["des","de","du","de les"],"correcta":1},{"p":"<i>Le raisin</i> es…","ops":["la pasa","la ciruela","la uva","la frambuesa"],"correcta":2},{"p":"¿Cómo se dice 2,50 €?","ops":["deux cinquante des euros","cinquante deux euros","deux euros de cinquante","deux euros cinquante"],"correcta":3}],"c-frances-a1-m5":[{"p":"En la recepción del hotel, ¿cuál es la forma más amable?","ops":["Je veux une chambre.","Je voudrais une chambre, s'il vous plaît.","Donnez une chambre.","Une chambre, maintenant."],"correcta":1},{"p":"El recepcionista dice <i>Désolé, l'hôtel est complet.</i> Significa que…","ops":["ya no hay habitaciones libres","el hotel tiene todos los servicios","el hotel está cerrado por obras","tu reservación está confirmada"],"correcta":0},{"p":"«La cuenta, por favor»","ops":["Le compte, s'il vous plaît.","La note, garçon!","L'addition, s'il vous plaît.","La facture du plat."],"correcta":2},{"p":"En un bistró, <i>le menu</i> es…","ops":["la carta completa","un paquete a precio fijo con entrada, plato y postre","el plato fuerte","la lista de bebidas"],"correcta":1},{"p":"«Ayer visité el museo»","ops":["Hier, je visite le musée.","Hier, je visité le musée.","Hier, j'ai visiter le musée.","Hier, j'ai visité le musée."],"correcta":3},{"p":"Passé composé de <i>prendre</i>:","ops":["j'ai prendu","j'ai pris","j'ai prené","j'ai prenu"],"correcta":1},{"p":"<i>Ma femme</i> significa…","ops":["mi esposa","mi hija","mi mamá","mi hermana"],"correcta":0},{"p":"Te invitan: <i>Tu veux venir dîner samedi?</i> Aceptas con…","ops":["Désolé, je ne peux pas.","De rien!","Avec plaisir!","Enchanté!"],"correcta":2}]}});
